  },
});

const PROVIDER_SPECS = Object.freeze({
  openrouter: {
    modelPrefix: 'openrouter',
    envKeys: ['OPENROUTER_API_KEY'],
  },
  hf: {
    modelPrefix: 'huggingface',
    envKeys: ['HUGGINGFACE_HUB_TOKEN', 'HF_TOKEN', 'HUGGINGFACE_API_KEY'],
  },
