    envKeys: ['NVIDIA_API_KEY'],
    customProviderBase: {
      baseUrl: 'https://integrate.api.nvidia.com/v1',
      api: 'openai-completions',
      auth: 'api-key',
      apiKey: {
        source: 'env',
        provider: 'default',
        id: 'NVIDIA_API_KEY',
      },
    },
  },
  ddeksee: {
    modelPrefix: 'deepseek',
    envKeys: ['DDEKSEE_API_KEY', 'DEEPSEEK_API_KEY'],
    customProviderBase: {
