// helpers for OpenClaw CLI detection and invocation
function looksLikeOpenClawDirectoryName(name) {
  const compact = String(name || '').toLowerCase().replace(/[\s._-]+/g, '');
  return compact.includes('openclaw');
}

function listOpenClawBinCandidates(baseDir) {
  const names = process.platform === 'win32'
    ? ['openclaw.cmd', 'openclaw.exe', 'openclaw.bat', 'openclaw']
    : ['openclaw'];
  const relPaths = [
    ['node_modules', '.bin'],
    ['.bin'],
    ['bin'],
    [],
  ];
  const out = [];
  for (const rel of relPaths) {
    for (const name of names) {
      out.push(path.join(baseDir, ...rel, name));
    }
  }
  return out;
}

function pickFirstExistingPath(paths) {
  for (const candidate of paths) {
    try {
      if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
        return candidate;
      }
    } catch {
      // ignore unreadable or transient files during discovery
    }
  }
  return '';
}

function listOpenClawGlobalCandidateRoots() {
  const roots = [];
  const homeDir = String(process.env.HOME || process.env.USERPROFILE || '').trim();
  if (!homeDir) {
    return roots;
  }
  roots.push(
    path.join(homeDir, '.local'),
    path.join(homeDir, '.local', 'nodejs', 'current'),
    path.join(homeDir, '.local', 'share', 'openclaw'),
    homeDir,
  );
  return Array.from(new Set(roots.filter(Boolean)));
}

function findOpenClawBinary(workspacePath) {
  const candidateRoots = [];
  if (workspacePath) {
    candidateRoots.push(workspacePath);

    try {
      const entries = fs.readdirSync(workspacePath, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isDirectory() && looksLikeOpenClawDirectoryName(entry.name)) {
          candidateRoots.push(path.join(workspacePath, entry.name));
        }
      }
    } catch {
      // ignore directory listing issues and keep PATH fallback
    }
  }
  candidateRoots.push(...listOpenClawGlobalCandidateRoots());
  const localBin = pickFirstExistingPath(
    Array.from(new Set(candidateRoots)).flatMap((root) => listOpenClawBinCandidates(root))
  );
  if (localBin) {
    return localBin;
  }
  return "openclaw";
}

async function runOpenClaw(args, output) {
  const folders = vscode.workspace.workspaceFolders;
  const workspacePath = folders && folders.length ? folders[0].uri.fsPath : process.cwd();
  const bin = findOpenClawBinary(workspacePath);
  output.appendLine(`[freejt7] invoking ${bin} ${args.join(" ")}`);
  const res = await runCommand(bin, args, { cwd: workspacePath }, output);
  if (res.code !== 0) {
    vscode.window.showErrorMessage(`Free JT7: openclaw CLI failed (code ${res.code}). See output.`);
  }
}

function createOpenClawTaggedError(message, flags = {}) {
  const error = new Error(message);
  Object.assign(error, flags);
  return error;
}

async function runOpenClawAgentTask(context, output, options = {}) {
  const provider = String(options.provider || '').trim();
  if (!provider || provider === 'copilot') {
    throw new Error('runOpenClawAgentTask requiere un proveedor externo valido.');
  }

  const workspacePath = String(options.workspacePath || getPrimaryWorkspacePath() || '').trim();
  if (!workspacePath) {
    throw createOpenClawTaggedError(
      'Free JT7: abre un workspace antes de usar modo agent con OpenClaw.',
      { isUserActionRequired: true, isConfigurationError: true, isRetryable: false },
    );
  }

  const model = String(options.model || getDefaultModel(provider) || '').trim();
  const authProfile = String(options.authProfile || 'default').trim() || 'default';
  const runtimeBackend = String(options.runtimeBackend || 'openclaw').trim() || 'openclaw';
  const policyProfile = String(options.policyProfile || 'coding').trim() || 'coding';
  const fallbackProviders = Array.isArray(options.fallbackProviders)
    ? options.fallbackProviders
    : [];
  const executionRoute = String(options.executionRoute || 'openclaw-agent').trim() || 'openclaw-agent';
  const apiKey = await getApiKey(provider, options.secretStorage, { workspacePath, model });
  if (!apiKey) {
    throw createOpenClawTaggedError(
      `Free JT7: falta la API key de ${provider} para ejecutar el modo agent via OpenClaw.`,
      { isUserActionRequired: true, isConfigurationError: true, isRetryable: false },
    );
  }

  await ensureMcpDependencies(context.extensionPath, output);

  const runtimeRoot = String(options.runtimeRoot || getOperationalRoot(context) || workspacePath).trim();
  const mcpServerEntry = path.join(context.extensionPath, 'servidor mpc free jt7', 'src', 'index.js');
  const ensured = ensureOpenClawRuntimeConfig(runtimeRoot, {
    provider,
    model,
    authProfile,
    policyProfile,
    fallbackModels: fallbackProviders,
    workspacePath,
    mcpCommand: 'node',
    mcpArgs: [mcpServerEntry],
  });
  if (ensured.changed) {
    output.appendLine(`[freejt7-openclaw] Config actualizada en ${ensured.configPath}`);
  }
  const lockCleanup = cleanupOpenClawStaleLocks(runtimeRoot);
  if (lockCleanup.removed.length > 0) {
    output.appendLine(`[freejt7-openclaw] Locks stale limpiados: ${lockCleanup.removed.length}`);
  }

  const env = buildOpenClawEnv(provider, apiKey, {
    ...process.env,
    OPENCLAW_CONFIG_PATH: ensured.configPath,
    OPENCLAW_STATE_DIR: ensured.stateDir,
    OPENCLAW_AUTH_PROFILE: authProfile,
  });
  const sessionId = buildOpenClawTaskSessionId(options);
  const bin = findOpenClawBinary(workspacePath);
  await ensureOpenClawGatewayAvailable(output, {
    bin,
    cwd: workspacePath,
    env,
    config: ensured.config,
    stateDir: ensured.stateDir,
  });
  const args = buildOpenClawAgentArgs({
    sessionId,
    message: String(options.serializedConversationGoal || options.goal || options.prompt || '').trim(),
    thinking: 'medium',
    timeoutSeconds: 600,
  });
  output.appendLine(`[freejt7-openclaw] Ejecutando modo agent provider=${provider} model=${normalizeOpenClawModel(provider, model)}`);
  let response = await runCommandCapture(
    bin,
    args,
    { cwd: workspacePath, env, timeoutMs: 620000 },
    output,
  );
  let rawOutput = `${response.stdout || ''}\n${response.stderr || ''}`.trim();
  let payload = extractJsonTail(response.stdout || rawOutput);
  let summary = summarizeOpenClawPayload(payload, rawOutput);

  if (response.code !== 0 && /session file locked|\.lock|timeout \d+ms/i.test(summary || rawOutput)) {
    const retrySessionId = `${sessionId || 'freejt7'}-${Date.now().toString(36)}`;
    const retryArgs = buildOpenClawAgentArgs({
      sessionId: retrySessionId,
      message: String(options.serializedConversationGoal || options.goal || options.prompt || '').trim(),
      thinking: 'medium',
      timeoutSeconds: 600,
    });
    const retryCleanup = cleanupOpenClawStaleLocks(runtimeRoot, { maxAgeMs: 1_000 });
    if (retryCleanup.removed.length > 0) {
      output.appendLine(`[freejt7-openclaw] Locks limpiados antes de reintento: ${retryCleanup.removed.length}`);
    }
    output.appendLine(`[freejt7-openclaw] Reintento por lock con sesion aislada ${retrySessionId}`);
    response = await runCommandCapture(
      bin,
      retryArgs,
      { cwd: workspacePath, env, timeoutMs: 620000 },
      output,
    );
    rawOutput = `${response.stdout || ''}\n${response.stderr || ''}`.trim();
    payload = extractJsonTail(response.stdout || rawOutput);
    summary = summarizeOpenClawPayload(payload, rawOutput);
  }

  if (response.code !== 0 || isOpenClawFailure({ code: response.code, summary })) {
    const detail = summary || rawOutput || `openclaw exit code ${response.code}`;
    const isAuth = /No API key found|token expired|incorrect|401|403|auth/i.test(detail);
    throw createOpenClawTaggedError(
      `Free JT7 (${provider}/OpenClaw agent): ${detail}`,
      {
        isUserActionRequired: isAuth,
        isConfigurationError: isAuth,
        isRetryable: !isAuth,
      },
    );
  }

  return {
    provider,
    model: model || getDefaultModel(provider) || '',
    executionMode: 'agent',
    executionRoute,
    rawOutput,
    payload,
    routeMeta: {
      runtimeBackend,
      authProfile,
      fallbackProviders,
      executionRoute,
    },
    run: {
      status: 'completed',
      summary,
      provider,
      model: model || getDefaultModel(provider) || '',
    },
    final: {
      status: 'completed',
      summary,
      changedFiles: [],
      verification: [
        `OpenClaw agent local ejecutado con ${provider}/${model || getDefaultModel(provider) || 'default'}.`,
        `MCP activo: free-jt7-local -> ${mcpServerEntry}.`,
        `Auth profile: ${authProfile}.`,
        `Runtime backend: ${runtimeBackend}.`,
      ],
      residualRisks: [],
    },
  };
}

function shouldUseLocalAgentFallback(goal, error, options = {}) {
  if (!canResolveLocalGoal(goal)) {
    return false;
  }
  const message = String(error && error.message ? error.message : error || '');
  if (options.forceForDeterministicGoal) {
    return true;
  }
  return Boolean(
    error?.isUserActionRequired
    || error?.isConfigurationError
    || /ENOENT|not found|no such file|falta la API key|openclaw|gateway|Agent couldn't generate a response|network connection error|timeout|timed out|ECONN|EHOST|socket hang up|HTTP 5\d\d|403 status code/i.test(message)
  );
}

function shouldUseProviderDirectFallback(error) {
  const message = String(error && error.message ? error.message : error || '');
  return Boolean(
    error?.isRetryable
    || error?.isRateLimitError
    || /FailoverError|session file locked|loopback|start the gateway|gateway|EADDRINUSE|EACCES|Agent couldn't generate a response|network connection error|timeout|timed out|ECONN|EHOST|socket hang up|HTTP 429|HTTP 5\d\d|403 status code/i.test(message)
  );
}

function shouldPreferLocalExecution(goal) {
  const text = String(goal || '').toLowerCase();
  if (!canResolveLocalGoal(goal)) {
    return false;
  }
  return /\b(instala|instalar|install)\b.*\bgit\b|\b(directorio siguiente:|el nombre de la car\w*ta|quecrees|mkdir)\b|\b(crea|crear|cree|crees)\b.*\b(carpeta|directorio)\b|\b(revisa|revise|inspecciona|inspeccione|lista|ls|verifica|verifique)\b.*\b(carpeta|directorio|ruta)\b|\blee\b.*\b(package\.json|readme|archivo)\b|\bverifica\b.*\b(build|test|script|archivo)\b|(?:porque|por que|why).*(?:no aparece|no sale|no se muestra).*(?:proveedor|provider|modelo|model)|(?:lista|interfaz|panel).*(?:proveedor|provider|modelo|model)|(?:proveedor|provider).*(?:deepseek|ddeksee)|(?:modelo|model).*(?:deepseek|ddeksee)|(?:po?r? ?que|porque|why).*(?:modo agente|agente).*(?:no funciona|no actua|no actúa|falla)|(?:chat basico|chat básico)|(?:verdadero agente ?autonomo|verdadero agente ?autónomo|agente ?autonomo|agente ?autónomo|agenteautonomo)/i.test(text);
}

async function runProviderDirectFallbackTask(context, output, options = {}) {
  const workspacePath = String(options.workspacePath || getPrimaryWorkspacePath() || context.extensionPath || process.cwd()).trim();
  const provider = String(options.provider || getEffectiveProviderConfig().provider || '').trim();
  const model = String(options.model || getEffectiveProviderConfig().model || '').trim();
  const authProfile = String(options.authProfile || 'default').trim() || 'default';
  if (!provider || provider === 'copilot') {
    throw new Error('Fallback directo requiere proveedor externo valido.');
  }

  const requestPayload = options.conversationRequest
    || String(options.serializedConversationGoal || options.goal || options.prompt || '').trim();
  const candidates = [
    { provider, model: model || getDefaultModel(provider) || '', authProfile },
    ...normalizeFallbackProviderEntries(provider, options.fallbackProviders)
      .map((entry) => ({
        provider: entry.provider,
        model: entry.model || getDefaultModel(entry.provider) || '',
        authProfile,
      })),
  ];
  const attempts = [];
  let direct = null;
  let selected = candidates[0];
  let lastError = null;

  for (let index = 0; index < candidates.length; index += 1) {
    const candidate = candidates[index];
    selected = candidate;
    try {
      output.appendLine(`[freejt7-provider-fallback] intento ${index + 1}/${candidates.length}: ${candidate.provider}/${candidate.model || 'default'}`);
      direct = await _callProvider(
        requestPayload,
        {
          provider: candidate.provider,
          model: candidate.model,
          authProfile: candidate.authProfile,
        },
        context.secrets,
        { workspacePath, authProfile: candidate.authProfile },
      );
      attempts.push({
        provider: candidate.provider,
        model: candidate.model || getDefaultModel(candidate.provider) || 'default',
        ok: true,
      });
      break;
    } catch (error) {
      lastError = error;
      attempts.push({
        provider: candidate.provider,
        model: candidate.model || getDefaultModel(candidate.provider) || 'default',
        ok: false,
        error: String(error?.message || error),
      });
      if (index >= candidates.length - 1) {
        break;
      }
      output.appendLine(`[freejt7-provider-fallback] fallo ${candidate.provider}: ${String(error?.message || error)}`);
    }
  }

  if (!direct) {
    const error = new Error(`Free JT7 provider fallback exhausted: ${String(lastError?.message || lastError || 'sin detalle')}`);
    error.attempts = attempts;
    if (lastError && typeof lastError === 'object') {
      error.isUserActionRequired = Boolean(lastError.isUserActionRequired);
      error.isConfigurationError = Boolean(lastError.isConfigurationError);
      error.isRetryable = Boolean(lastError.isRetryable);
      error.isRateLimitError = Boolean(lastError.isRateLimitError);
    }
    throw error;
  }

  const summary = String(direct?.run?.summary || direct?.final?.summary || direct?.summary || 'ok').trim() || 'ok';
  const existingVerification = Array.isArray(direct?.final?.verification)
    ? direct.final.verification.filter(Boolean).map((item) => String(item))
    : [];
  const selectedProvider = selected.provider;
  const selectedModel = selected.model || getDefaultModel(selected.provider) || '';
  const switchedProvider = selectedProvider !== provider || selectedModel !== (model || getDefaultModel(provider) || '');
  const verificationLine = switchedProvider
    ? `Fallback directo cambio de ${provider}/${model || getDefaultModel(provider) || 'default'} a ${selectedProvider}/${selectedModel || 'default'} por indisponibilidad temporal del backend principal.`
    : `Fallback directo ${selectedProvider}/${selectedModel || 'default'} aplicado por indisponibilidad temporal del runtime agente OpenClaw.`;

  return {
    ...direct,
    provider: selectedProvider,
    model: selectedModel,
    executionMode: 'agent',
    executionRoute: 'provider-direct-fallback',
    routeMeta: {
      runtimeBackend: String(options.runtimeBackend || 'auto').trim().toLowerCase() || 'auto',
      fallback: 'provider-direct',
      fallbackReason: String(options.fallbackReason || '').trim(),
      fallbackAttempts: attempts,
    },
    run: {
      ...(direct?.run || {}),
      status: 'completed',
      summary,
      provider: selectedProvider,
      model: selectedModel,
    },
    final: {
      ...(direct?.final || {}),
      status: 'completed',
      summary,
      changedFiles: Array.isArray(direct?.final?.changedFiles) ? direct.final.changedFiles : [],
      verification: [
        ...existingVerification,
        verificationLine,
      ],
      residualRisks: [
        'La ejecucion uso fallback directo del proveedor; capacidades completas de herramientas/agente pueden estar degradadas hasta recuperar OpenClaw.',
      ],
    },
  };
}

async function runFreeJt7OwnedAgentTask(context, output, options = {}) {
  const workspacePath = String(options.workspacePath || getPrimaryWorkspacePath() || context.extensionPath || process.cwd()).trim();
  const provider = String(options.provider || getEffectiveProviderConfig().provider || '').trim();
  const model = String(options.model || getEffectiveProviderConfig().model || '').trim();
  const authProfile = String(options.authProfile || 'default').trim() || 'default';
  const runtimeBackend = 'freejt7';

  if (!provider || provider === 'copilot') {
    throw new Error('Backend propio de Free JT7 requiere un proveedor externo valido.');
  }

  output.appendLine(`[freejt7-owned] Ejecutando backend propio agentic provider=${provider} model=${model || 'default'}`);

  const ownedRuntime = createFreeJt7OwnedRuntime({
    callProvider: _callProvider,
    executeLocalActions,
    deriveLocalActions,
    listWorkspace,
    readPackageSummary,
  });

  try {
    const result = await ownedRuntime.executeTask(context, output, {
      ...options,
      workspacePath,
      provider,
      model,
      authProfile,
      runtimeBackend,
      fallbackReason: String(options.fallbackReason || 'freejt7-owned-primary').trim(),
    });
    return {
      ...result,
      executionMode: 'agent',
      executionRoute: 'freejt7-owned-agent',
      routeMeta: {
        ...(result?.routeMeta || {}),
        runtimeBackend,
        backend: buildSubordinateBackendDescriptor({
          executionRoute: 'freejt7-owned-agent',
          runtimeBackend,
          provider: result?.provider || provider,
          model: result?.model || model,
          authProfile,
          fallbackSelected: '',
        }),
      },
      final: {
        ...(result?.final || {}),
        verification: [
          'Backend propio Free JT7 ejecuto loop agentico real sin depender de OpenClaw como ruta principal.',
          ...(Array.isArray(result?.final?.verification) ? result.final.verification.filter(Boolean).map((item) => String(item)) : []),
        ],
      },
    };
  } catch (error) {
    output.appendLine(`[freejt7-owned] proveedor primario del backend propio fallo: ${String(error?.message || error)}`);
    throw error;
  }
}

async function runFreeJt7LocalAgentTask(context, output, options = {}) {
  const workspacePath = String(options.workspacePath || getPrimaryWorkspacePath() || context.extensionPath || process.cwd()).trim();
  const provider = String(options.provider || getEffectiveProviderConfig().provider || 'local').trim();
  const model = String(options.model || getEffectiveProviderConfig().model || 'freejt7-local-tools').trim();
  output.appendLine(`[freejt7-local-agent] Ejecutando herramientas locales provider=${provider} model=${model}`);
  return runLocalAgentTask(String(options.goal || options.prompt || '').trim(), {
    ...options,
    workspacePath,
    provider,
    model,
  });
}

async function runFreeJt7AcpTask(context, output, options = {}) {
  const runtimeBackend = String(options.runtimeBackend || '').trim().toLowerCase();
  const harness = runtimeBackend.startsWith('acp:')
    ? runtimeBackend.split(':').slice(1).join(':') || 'codex'
    : 'codex';
  const provider = String(options.provider || getEffectiveProviderConfig().provider || '').trim();
  const model = String(options.model || getEffectiveProviderConfig().model || '').trim();
  output.appendLine(`[freejt7-acp] runtime=${runtimeBackend || 'acp'} harness=${harness} provider=${provider || 'auto'} model=${model || 'default'}`);

  if (provider && provider !== 'copilot') {
    try {
      return await runOpenClawAgentTask(context, output, {
        ...options,
        provider,
        model,
        runtimeBackend,
        executionRoute: `acp:${harness}`,
      });
    } catch (error) {
      output.appendLine(`[freejt7-acp] Fallback local por fallo ACP/OpenClaw: ${String(error?.message || error)}`);
      if (shouldPreferLocalExecution(options.goal || options.prompt || '')) {
        return runFreeJt7LocalAgentTask(context, output, {
          ...options,
          provider: provider || 'local',
          model: model || `acp-${harness}-local`,
          runtimeBackend: runtimeBackend || `acp:${harness}`,
          fallbackReason: String(error?.message || error),
        });
      }
      if (shouldUseProviderDirectFallback(error)) {
        try {
          return await runProviderDirectFallbackTask(context, output, {
            ...options,
            provider,
            model,
            runtimeBackend: runtimeBackend || `acp:${harness}`,
            fallbackReason: String(error?.message || error),
          });
        } catch (directError) {
          output.appendLine(`[freejt7-acp] Fallback directo provider falló: ${String(directError?.message || directError)}`);
          if (shouldUseLocalAgentFallback(options.goal || options.prompt || '', error, { forceForDeterministicGoal: true })) {
            return runFreeJt7LocalAgentTask(context, output, {
              ...options,
              provider: provider || 'local',
              model: model || `acp-${harness}-local`,
              runtimeBackend: runtimeBackend || `acp:${harness}`,
              fallbackReason: String(directError?.message || directError),
            });
          }
        }
      }
      if (!shouldUseLocalAgentFallback(options.goal || options.prompt || '', error)) {
        throw error;
      }
    }
  }

  const local = await runFreeJt7LocalAgentTask(context, output, {
    ...options,
    provider: provider || 'local',
    model: model || `acp-${harness}-local`,
    runtimeBackend: runtimeBackend || `acp:${harness}`,
    fallbackReason: 'ACP fallback local',
  });
  return {
    ...local,
    executionRoute: `acp:${harness}:local-fallback`,
    routeMeta: {
      runtimeBackend: runtimeBackend || `acp:${harness}`,
      harness,
      fallback: 'local',
    },
  };
}

async function handleChatRequest(context, output, request, chatContext, stream) {
  const command = request.command || "route";
  const activeProviderConfig = getEffectiveProviderConfig();
  const workspacePathForConversation = getPrimaryWorkspacePath() || context.extensionPath;
  const priorMessages = extractChatContextMessages(chatContext);

  if (command === "docs") {
    openRuntimeDocs(context);
    stream.markdown("Abrí la documentación de Free JT7 en el editor.");
    return { metadata: { command } };
  }

  if (command === "doctor") {
    stream.progress("Validando el runtime de Free JT7...");
    const result = await runtimeDoctor(context, output);
    stream.markdown(result?.message || "Runtime validado.");
    return { metadata: { command, ok: Boolean(result?.ok) } };
  }

  if (command === "install") {
    const workspacePath = getPrimaryWorkspacePath();
    stream.progress(workspacePath ? "Instalando Free JT7 en el workspace actual..." : "Aplicando configuracion global multi-IDE...");
    const result = workspacePath ? await installWorkspace(context, output) : await installGlobalMultiIde(context, output);
    stream.markdown(result?.message || "Instalacion finalizada.");
    return { metadata: { command, ok: Boolean(result?.ok) } };
  }

  if (command === "global") {
    stream.progress("Aplicando configuracion global multi-IDE...");
    const result = await installGlobalMultiIde(context, output);
    stream.markdown(result?.message || "Configuracion global finalizada.");
    return { metadata: { command, ok: Boolean(result?.ok) } };
  }

  const prompt = String(request.prompt || "").trim();
  if (!prompt) {
    stream.markdown("Escribe una solicitud para `@freejt7` o usa `/doctor`, `/install` o `/docs`.");
    return { metadata: { command, ok: false } };
  }

  if (activeProviderConfig.provider !== "copilot") {
    const activeModelLabel = activeProviderConfig.model || "default";
    stream.markdown(
      `Aviso: esta solicitud entra por GitHub Copilot Chat como host. La ejecución de Free JT7 se delegará a ${activeProviderConfig.provider} / ${activeModelLabel}, pero la apertura de este chat puede seguir contabilizando uso del host Copilot. Si quieres evitar ese consumo del host, usa el comando "Free JT7: Ejecutar tarea directa con proveedor activo".`
    );
  }

  stream.progress("Recogiendo intake obligatorio de Free JT7...");
  try {
    const preparedTask = await prepareAuditedTask(context, output, prompt);
    if (!preparedTask) {
      stream.markdown("Se canceló el intake obligatorio. Vuelve a lanzar la tarea cuando quieras continuar.");
      return { metadata: { command, ok: false, cancelled: true } };
    }
    preparedTask.conversationRequest = buildConversationRequest({
      prompt: preparedTask.goal,
      history: priorMessages,
      sessionTitle: 'VS Code Chat',
      workspacePath: workspacePathForConversation,
      channel: 'chat-participant',
    });
    stream.progress("Ejecutando el router auditado de Free JT7...");
    const result = await routeTaskWithGoal(context, output, preparedTask);
    stream.markdown(formatRouterMarkdown(result));
    return {
      metadata: {
        command,
        ok: true,
        runId: result?.runId || "",
      },
    };
  } catch (error) {
    const message = String(error && error.message ? error.message : error);
    output.appendLine(`[freejt7-chat] ERROR ${message}`);
    stream.markdown(`Free JT7 no pudo completar la tarea.\n\n${message}`);
    return { metadata: { command, ok: false, error: message } };
  }
}

async function ensureMcpDependencies(extensionPath, output) {
  const mcpDir = path.join(extensionPath, "servidor mpc free jt7");
  const mcpCheck = path.join(mcpDir, "node_modules", "@modelcontextprotocol");
  if (!fs.existsSync(mcpCheck)) {
    output.appendLine("[freejt7] ⚠️ Dependencias MCP no encontradas, instalando...");
    try {
      await runCommand("npm", ["install", "--production"], { cwd: mcpDir }, output);
      output.appendLine("[freejt7] ✅ Dependencias MCP instaladas correctamente.");
    } catch (e) {
      output.appendLine(`[freejt7] ❌ Error instalando deps MCP: ${e.message}`);
    }
  }
}

function activate(context) {
  let providerStatusBar;
  const output = vscode.window.createOutputChannel("Free JT7");
  const chatDiagnostics = getChatDiagnostics();
  if (!chatDiagnostics.ok) {
    for (const issue of chatDiagnostics.issues) {
      output.appendLine(`[freejt7] ${issue}`);
    }
  }
  // FIX #4: Check Python disponible
  const pyCmd = pythonCommand(context.extensionPath);
  if (!isWorkingPython(pyCmd.bin, pyCmd.args)) {
    output.appendLine("[freejt7] ⚠️ Python no encontrado en el sistema.");
    vscode.window.showWarningMessage(
      "Free JT7: Python no encontrado. Instale Python 3 y reinicie VS Code.",
      "Descargar Python"
    ).then(action => {
      if (action === "Descargar Python")
        vscode.env.openExternal(vscode.Uri.parse("https://www.python.org/downloads/"));
    });
  }

  // FIX #3: Check OpenClaw disponible
  const wsPath = getPrimaryWorkspacePath();
  const clawBin = findOpenClawBinary(wsPath);
  if (clawBin === "openclaw") {
    const clawCheck = spawnSync("openclaw", ["--version"], { shell: true });
    if (clawCheck.error || clawCheck.status !== 0) {
      output.appendLine("[freejt7] ⚠️ OpenClaw CLI no encontrado en PATH.");
      vscode.window.showWarningMessage(
        "Free JT7: OpenClaw CLI no encontrado. Instálalo con: npm install -g openclaw",
        "Más información"
      ).then(action => {
        if (action === "Más información")
          vscode.env.openExternal(vscode.Uri.parse("https://github.com/openclaw/openclaw#readme"));
      });
    }
  }

  // FIX #2: Verificar/instalar deps MCP en background
  ensureMcpDependencies(context.extensionPath, output).catch(e =>
    output.appendLine(`[freejt7] ensureMcpDependencies error: ${e}`)
  );

  Promise.resolve()
    .then(() => ensureGlobalVsCodeSettings(context, output))
    .then(() => ensureWorkspaceBridge(context, output))
    .catch((error) => {
      output.appendLine(`[freejt7] bootstrap global/workspace error: ${String(error?.message || error)}`);
    });

  // P4 Wire-C: start memory orchestrator + scheduler (non-fatal)
  const operationalRoot = getOperationalRoot(context);
  try {
    getRemoteBridge({ rootDir: operationalRoot }).start();
    const pluginRuntime = getPluginRuntime();
    const integrationDiscovery = pluginRuntime.discoverAndLoadIntegrations({
      directories: [path.join(operationalRoot, 'integrations')],
      allowExperimental: false,
    });
    const _orch = new MemoryOrchestrator({ workspacePath: operationalRoot });
    activeScheduler = createDefaultScheduler({ rootDir: operationalRoot }, _orch);
    activeScheduler.start();
    output.appendLine('[freejt7] Scheduler runtime inicializado.');
    if (integrationDiscovery.loaded.length > 0) {
      output.appendLine(`[freejt7] Capability packs cargados: ${integrationDiscovery.loaded.length}`);
    }
  } catch (_) { /* non-fatal — scheduler must never crash extension startup */ }

  const panelConfig = vscode.workspace.getConfiguration("freejt7");
  const panelEnabled = panelConfig.get("panel.enabled", true);
  if (panelEnabled) {
    try {
      const ownAgentRuntime = createFreeJt7AgentRuntime({
        context,
        output,
        runtimeRoot: operationalRoot,
        getWorkspacePath: () => getPrimaryWorkspacePath(),
        getProviderConfig: () => getEffectiveProviderConfig(),
        runLocalAgentTask: runFreeJt7LocalAgentTask,
        runOwnedAgentTask: runFreeJt7OwnedAgentTask,
        runOpenClawAgentTask,
        runProviderDirectFallbackTask,
        runAcpTask: runFreeJt7AcpTask,
        runCopilotTask: async (goal, taskContext = {}) => {
          const workspacePath = getPrimaryWorkspacePath();
          if (!workspacePath) {
            throw new Error("Free JT7: abre un workspace antes de usar Copilot Pro desde el panel.");
          }
          const copilotGoal = taskContext?.conversationRequest
            ? serializeConversationRequest(taskContext.conversationRequest)
            : goal;
          return runCopilotRouter({
            goal: copilotGoal,
            workspacePath,
            vscode,
            output,
            extensionPath: context.extensionPath,
            secretStorage: context.secrets,
            runId: taskContext?.runId || "",
            selectedSkills: Array.isArray(taskContext?.selectedSkills) && taskContext.selectedSkills.length
              ? taskContext.selectedSkills
              : DEFAULT_ROUTER_SKILLS,
            intake: taskContext?.intake || null,
            providerOverride: "copilot",
            modelOverride: "",
          });
        },
        shouldPreferLocalExecution,
        canResolveLocalGoal,
        buildLocalActions: (goal, taskContext = {}) => deriveLocalActions(goal, taskContext),
        getMcpServers: () => ([
          {
            id: 'free-jt7-local',
            transport: 'stdio',
            enabled: true,
          },
        ]),
        shouldUseProviderDirectFallback,
        shouldUseLocalAgentFallback,
      });

      activeControlPanel = createControlPanel(context, output, {
        workspacePath: operationalRoot,
        workerCount: Number(panelConfig.get("panel.workerPool.size", 3) || 3),
        policyMode: String(panelConfig.get("panel.policy.mode", "mixed") || "mixed"),
        remoteBridge: getRemoteBridge({ rootDir: operationalRoot }),
        agentRuntime: ownAgentRuntime,
        prepareTask: async (taskInput, meta) => preparePanelTask(context, output, taskInput, meta),
        finalizeTaskTrace: async (task, summary) => closeTrackedTask(context, output, task.runId, summary),
        executeCopilotTask: async (goal, taskContext = {}) => {
          const workspacePath = getPrimaryWorkspacePath();
          if (!workspacePath) {
            throw new Error("Free JT7: abre un workspace antes de usar Copilot Pro desde el panel.");
          }
          return runCopilotRouter({
            goal,
            workspacePath,
            vscode,
            output,
            extensionPath: context.extensionPath,
            secretStorage: context.secrets,
            runId: taskContext?.runId || "",
            selectedSkills: Array.isArray(taskContext?.selectedSkills) && taskContext.selectedSkills.length
              ? taskContext.selectedSkills
              : DEFAULT_ROUTER_SKILLS,
            intake: taskContext?.intake || null,
          });
        },
        executeAcpTask: async (goal, taskContext = {}) => {
          const workspacePath = getPrimaryWorkspacePath();
          if (!workspacePath) {
            throw new Error("Free JT7: abre un workspace antes de usar backend ACP.");
          }
          return runFreeJt7AcpTask(context, output, {
            goal,
            workspacePath,
            runtimeRoot: operationalRoot,
            provider: String(taskContext?.provider || getEffectiveProviderConfig().provider || '').trim(),
            model: String(taskContext?.model || getEffectiveProviderConfig().model || '').trim(),
            runtimeBackend: String(taskContext?.runtimeBackend || 'acp:codex').trim().toLowerCase(),
            authProfile: String(taskContext?.authProfile || 'default').trim(),
            policyProfile: String(taskContext?.policyProfile || 'coding').trim(),
            fallbackProviders: Array.isArray(taskContext?.fallbackProviders) ? taskContext.fallbackProviders : [],
            sessionId: String(taskContext?.sessionId || '').trim(),
            runId: String(taskContext?.runId || '').trim(),
            secretStorage: context.secrets,
          });
        },
        executeAgentTask: async (goal, taskContext = {}) => {
          return ownAgentRuntime.executeAgentTask(goal, {
            ...taskContext,
            runtimeRoot: operationalRoot,
            secretStorage: context.secrets,
          });
        },
      });
      output.appendLine("[freejt7-panel] Control panel runtime inicializado.");
    } catch (error) {
      output.appendLine(`[freejt7-panel] init error: ${String(error?.message || error)}`);
    }
  }

  const subscriptions = [
    vscode.commands.registerCommand("freejt7.installWorkspace", () => installWorkspace(context, output)),
    vscode.commands.registerCommand("freejt7.installGlobalVsCode", () => installGlobalVsCode(context, output)),
    vscode.commands.registerCommand("freejt7.installGlobalMultiIde", () => installGlobalMultiIde(context, output)),
    vscode.commands.registerCommand("freejt7.runtimeDoctor", () => runtimeDoctor(context, output)),
    vscode.commands.registerCommand("freejt7.openRuntimeDocs", () => openRuntimeDocs(context)),
    vscode.commands.registerCommand("freejt7.routeTaskWithCopilot", () => routeTaskWithCopilot(context, output)),
    vscode.commands.registerCommand("freejt7.routeTaskDirect", () => routeTaskWithCopilot(context, output)),
    vscode.commands.registerCommand("freejt7.openControlPanel", () => {
      if (!activeControlPanel) {
        vscode.window.showErrorMessage("Free JT7: el panel esta deshabilitado en freejt7.panel.enabled.");
        return;
      }
      activeControlPanel.openPanel();
    }),
    vscode.commands.registerCommand("freejt7.launchDesignAgent", () => launchDesignAgent(context, output)),

    // new commands exposing OpenClaw CLI
    vscode.commands.registerCommand("freejt7.openClawGatewayStatus", () => runOpenClaw(["gateway", "status"], output)),
    vscode.commands.registerCommand("freejt7.openClawCLI", async () => {
      const argStr = await vscode.window.showInputBox({ prompt: "Args for openclaw", value: "" });
      if (argStr !== undefined) {
        const args = argStr.match(/(?:[^\"\s]|\"[^\"]*\")+/g) || [];
        await runOpenClaw(args, output);
      }
    }),
    // new helper to start gateway if user wants
    vscode.commands.registerCommand("freejt7.openClawStartGateway", () => runOpenClaw(["gateway","--port","18789"], output)),
    // helper for editing config file in user's home
    vscode.commands.registerCommand("freejt7.editOpenClawConfig", async () => {
      const home = process.env.HOME || process.env.USERPROFILE;
      const cfg = path.join(home, ".openclaw", "openclaw.json");
      if (!fs.existsSync(cfg)) {
        vscode.window.showErrorMessage(`Free JT7: no existe el archivo de configuracion ${cfg}`);
        return;
      }
      const doc = await vscode.workspace.openTextDocument(cfg);
      vscode.window.showTextDocument(doc, { preview: false });
    }),
    // additional wrappers for common OpenClaw actions
    vscode.commands.registerCommand("freejt7.openClawInstallService", () => runOpenClaw(["onboard","--install-daemon"], output)),
    vscode.commands.registerCommand("freejt7.openClawACP", async () => {
      const argStr = await vscode.window.showInputBox({ prompt: "Args for openclaw acp", value: "" });
      if (argStr !== undefined) {
        const args = ["acp", ... (argStr.match(/(?:[^\"\s]|\"[^\"]*\")+/g) || [])];
        await runOpenClaw(args, output);
      }
    }),
    vscode.commands.registerCommand("freejt7.openClawChannelsLogin", () => runOpenClaw(["channels","login"], output)),
    vscode.commands.registerCommand("freejt7.selectApiProvider", async () => {
      const providers = listSelectableApiProviders();
      const picked = await vscode.window.showQuickPick(providers, { placeHolder: "Selecciona el proveedor de API" });
      if (!picked) return;
      let model = "";
      if (picked.value !== "copilot") {
        const currentConfig = getEffectiveProviderConfig();
        const currentModel = currentConfig.provider === picked.value
          ? currentConfig.model
          : (getDefaultModel(picked.value) || "");
        const items = buildModelQuickPickItems(picked.value, currentModel);
        if (items.length > 0) {
          items.push({ label: "✏️ Escribir manualmente...", description: "" });
          const selection = await vscode.window.showQuickPick(items, {
            placeHolder: `Modelo verificado para ${picked.value} (actual: ${currentModel || "ninguno"})`,
          });
          if (!selection) return;
          if (selection.label === "✏️ Escribir manualmente...") {
            model = await vscode.window.showInputBox({
              prompt: `Modelo para ${picked.value}`,
              value: currentModel,
            }) || "";
          } else {
            model = selection.modelValue || "";
          }
        } else {
          model = await vscode.window.showInputBox({
            prompt: `Modelo para ${picked.value} (deja vacío para usar el predeterminado)`,
            value: currentModel,
          }) || getDefaultModel(picked.value) || "";
        }
      }
      const config = vscode.workspace.getConfiguration("freejt7");
      await config.update("apiProvider", picked.value, vscode.ConfigurationTarget.Global);
      await config.update("apiProviderModel", model, vscode.ConfigurationTarget.Global);
      updateProviderStatusBar(providerStatusBar);
      output.appendLine(`[freejt7] Proveedor cambiado a: ${picked.value} ${model ? `(${model})` : ""}`);
      vscode.window.showInformationMessage(`Free JT7: proveedor → ${picked.value}${model ? ` / ${model}` : ""}`);
    }),
    vscode.commands.registerCommand("freejt7.setApiKey", async () => {
      const providers = listProviders({ includeCopilot: false })
        .filter((provider) => provider && provider.id && provider.id !== 'copilot')
        .map((provider) => ({
          label: provider.label,
          value: provider.id,
        }));
      const picked = await vscode.window.showQuickPick(providers, { placeHolder: "¿Para qué proveedor deseas configurar la API key?" });
      if (!picked) return;
      const providerMeta = getProvider(picked.value) || { apiKeyMode: "provider" };
      let secretKey = `freejt7.apiKey.${picked.value}`;
      let targetLabel = picked.label;
      if (providerMeta.apiKeyMode === "per-model") {
        const activeConfig = getEffectiveProviderConfig();
        const currentModel = activeConfig.provider === picked.value
          ? activeConfig.model
          : getDefaultModel(picked.value);
        const modelItems = buildModelQuickPickItems(picked.value, currentModel);
        const modelSelection = await vscode.window.showQuickPick(modelItems, {
          placeHolder: `¿Para qué modelo de ${picked.label} deseas configurar la API key?`,
        });
        if (!modelSelection) return;
        const normalizedModelKey = String(modelSelection.modelValue || "")
          .trim()
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, ".")
          .replace(/^\.+|\.+$/g, "");
        if (!normalizedModelKey) {
          vscode.window.showErrorMessage(`Free JT7: no pude normalizar el id del modelo de ${picked.label}.`);
          return;
        }
        secretKey = `freejt7.apiKey.${picked.value}.${normalizedModelKey}`;
        targetLabel = `${picked.label} / ${modelSelection.modelValue}`;
      }
      const key = await vscode.window.showInputBox({
        prompt: `API Key para ${targetLabel}`,
        password: true,
        ignoreFocusOut: true,
      });
      if (!key) return;
      await context.secrets.store(secretKey, key);
      output.appendLine(`[freejt7] API key guardada para: ${targetLabel}`);
      vscode.window.showInformationMessage(`Free JT7: API key configurada para ${targetLabel}`);
    }),
    vscode.commands.registerCommand("freejt7.selectFreeModel", async () => {
      const config = vscode.workspace.getConfiguration("freejt7");
      const { provider, model: activeModel } = getEffectiveProviderConfig();
      if (provider === "copilot") {
        vscode.window.showInformationMessage("Copilot usa su modelo integrado. Cambia de proveedor primero.");
        return;
      }
      const freeModels = getModelsForProvider(provider);
      if (freeModels.length === 0) {
        vscode.window.showWarningMessage(`No hay modelos gratuitos catalogados para ${provider}.`);
        return;
      }
      const items = buildModelQuickPickItems(provider, activeModel);
      const selection = await vscode.window.showQuickPick(items, { placeHolder: `Selecciona modelo verificado para ${provider}` });
      if (!selection) return;
      await config.update("apiProviderModel", selection.modelValue, vscode.ConfigurationTarget.Global);
      updateProviderStatusBar(providerStatusBar);
      output.appendLine(`[freejt7] Modelo cambiado a: ${selection.modelValue}`);
      vscode.window.showInformationMessage(`Free JT7: modelo → ${selection.modelValue}`);
    }),
    vscode.commands.registerCommand("freejt7.refreshFreeModels", () => {
      freeModelsCatalog = loadFreeModelsCatalog();
      updateProviderStatusBar(providerStatusBar);
      output.appendLine("[freejt7] Catálogo de modelos gratuitos recargado en runtime.");
      vscode.window.showInformationMessage("Free JT7: catálogo de modelos actualizado.");
    }),
    vscode.commands.registerCommand("freejt7.testApiProvider", async () => {
      const { provider, model } = getEffectiveProviderConfig();
      if (provider === "copilot") {
        vscode.window.showInformationMessage("Free JT7: Copilot usa autenticación GitHub — no requiere test de conexión externo.");
        return;
      }
      output.appendLine(`[freejt7] Probando conexión: provider=${provider} model=${model || "default"}`);
      output.show(true);
      vscode.window.showInformationMessage(`Free JT7: probando conexión con ${provider}...`);
      try {
        const workspacePathForProvider = getPrimaryWorkspacePath() || context.extensionPath;
        const result = await _callProvider(
          "Responde solo con la palabra ok.",
          { provider, model },
          context.secrets,
          { workspacePath: workspacePathForProvider },
        );
        const summary = String(result?.run?.summary || result?.final?.summary || "ok").slice(0, 150);
        output.appendLine(`[freejt7] Conexión OK con ${provider}: ${summary}`);
        vscode.window.showInformationMessage(`Free JT7: conexion con ${provider} verificada ✓. Respuesta: ${summary.slice(0, 80)}`);
      } catch (err) {
        const msg = String(err?.message || err).slice(0, 300);
        output.appendLine(`[freejt7] Error al probar ${provider}: ${msg}`);
        vscode.window.showErrorMessage(`Free JT7: fallo la conexion con ${provider}. ${msg}`);
      }
    }),
    output,
  ];

  // Status bar del proveedor activo
  providerStatusBar = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 1000);
  providerStatusBar.command = "freejt7.selectApiProvider";
  updateProviderStatusBar(providerStatusBar);
  providerStatusBar.show();
  subscriptions.push(providerStatusBar);

  if (vscode.workspace?.onDidChangeConfiguration) {
    subscriptions.push(vscode.workspace.onDidChangeConfiguration((event) => {
      if (event.affectsConfiguration("freejt7.apiProvider") || event.affectsConfiguration("freejt7.apiProviderModel")) {
        updateProviderStatusBar(providerStatusBar);
      }
    }));
  }

  const chatParticipantEnabled = panelConfig.get("panel.chatParticipant.enabled", true);
  if (chatParticipantEnabled && vscode.chat?.createChatParticipant) {
    const participant = vscode.chat.createChatParticipant("freejt7.chat", (request, chatContext, stream, token) => (
      handleChatRequest(context, output, request, chatContext, stream, token)
    ));
    subscriptions.push(participant);
  } else if (!chatParticipantEnabled) {
    output.appendLine("[freejt7-panel] chat participant deshabilitado por configuracion.");
  }

  const sidebarProvider = {
    resolveWebviewView(webviewView) {
      webviewView.webview.options = { enableScripts: true, enableCommandUris: true };
      webviewView.webview.html = `
        <!doctype html>
        <html lang="es">
        <body style="margin:0;padding:12px;font-family:Segoe UI,sans-serif;color:var(--vscode-foreground);background:var(--vscode-editor-background);">
          <div style="display:flex;flex-direction:column;gap:8px;">
            <div style="font-weight:600;">Agente Free JT7</div>
            <div style="opacity:.8;">Si la superficie principal del agente no se abrió sola, usa este acceso directo.</div>
            <a href="command:freejt7.openControlPanel" style="color:var(--vscode-textLink-foreground);text-decoration:none;">Abrir agente Free JT7</a>
          </div>
        </body>
        </html>
      `;
      void vscode.commands.executeCommand('freejt7.openControlPanel');
    }
  };
  context.subscriptions.push(
    vscode.window.registerWebviewViewProvider('freejt7.controlPanelView', sidebarProvider)
  );

  if (shouldAutoOpenControlPanel(panelConfig, { standaloneMode: isStandaloneOwnIdeMode() })) {
    setTimeout(() => {
      revealFreeJt7ControlPanel(activeControlPanel, output).catch((error) => {
        output.appendLine(`[freejt7-panel] auto-open error: ${String(error?.message || error)}`);
      });
    }, 250);
  }

  context.subscriptions.push(...subscriptions);
}

function deactivate() {
  if (activeScheduler && typeof activeScheduler.stop === 'function') {
    activeScheduler.stop();
    activeScheduler = null;
  }
  if (activeControlPanel && typeof activeControlPanel.dispose === 'function') {
    activeControlPanel.dispose();
    activeControlPanel = null;
  }
  getRemoteBridge().stop();
}

// expose helper for external tests
module.exports = {
  activate,
  deactivate,
  runOpenClaw,
  runProviderDirectFallbackTask,
  findOpenClawBinary,
  getGlobalVsCodeSettingsRepairState,
  getEffectiveAgentAuthorityConfig,
  resolveProviderFallbackChain,
  shouldAutoOpenControlPanel,
  shouldPreferLocalExecution,
  shouldUseLocalAgentFallback,
  shouldUseProviderDirectFallback,
};

'use strict';

const {
  buildConversationRequest,
  serializeConversationRequest,
} = require('./chat-context');
const { buildSubordinateBackendDescriptor } = require('./openclaw-agent-runtime');
const { getAgentFacade, isExternalProvider } = require('./provider-registry');

function noop() {}

function cloneJson(value) {
  return value == null ? value : JSON.parse(JSON.stringify(value));
}

function normalizeSkillId(skill) {
  if (!skill) return '';
  if (typeof skill === 'string') return skill.trim();
  if (typeof skill === 'object') {
    return String(skill.id || skill.name || skill.label || '').trim();
  }
  return '';
}

function uniqueStrings(values = []) {
  const seen = new Set();
  const result = [];
  for (const value of values) {
    const normalized = String(value || '').trim();
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    result.push(normalized);
  }
  return result;
}

function normalizeMcpServers(servers = []) {
  return Array.isArray(servers)
    ? servers
      .map((server) => {
        if (!server || typeof server !== 'object') return null;
        const id = String(server.id || server.name || '').trim();
        if (!id) return null;
        return {
          id,
          transport: String(server.transport || 'stdio').trim() || 'stdio',
          enabled: server.enabled !== false,
        };
      })
      .filter(Boolean)
    : [];
}

function inferNativeMcpTools(goal, mcpServers = []) {
  if (!Array.isArray(mcpServers) || !mcpServers.some((server) => server && server.enabled !== false)) {
    return [];
  }
  const text = String(goal || '').toLowerCase();
  return [
    /\b(pdf|json|markdown|md\b|documento|document|archivo|ruta|directorio|buscar contenido|contenido)\b/.test(text)
      ? { family: 'documents', reason: 'goal-document-or-path' }
      : null,
    /\b(web|browser|navegador|url|duckduckgo|google|buscar en la web|search web|internet)\b/.test(text)
      ? { family: 'browser', reason: 'goal-web-navigation' }
      : null,
    /\b(abrir|revela|revelar|mostrar en carpeta|explorer|finder|desktop|escritorio)\b/.test(text)
      ? { family: 'desktop', reason: 'goal-desktop-open' }
      : null,
  ].filter(Boolean);
}

function createFreeJt7AgentRuntime(options = {}) {
  const output = options.output || { appendLine: noop };
  const context = options.context || {};
  const agentFacade = getAgentFacade();
  const getWorkspacePath = typeof options.getWorkspacePath === 'function'
    ? options.getWorkspacePath
    : (() => '');
  const getProviderConfig = typeof options.getProviderConfig === 'function'
    ? options.getProviderConfig
    : (() => ({ provider: '', model: '' }));
  const runLocalAgentTask = options.runLocalAgentTask;
  const runOwnedAgentTask = options.runOwnedAgentTask;
  const runOpenClawAgentTask = options.runOpenClawAgentTask;
  const runProviderDirectFallbackTask = options.runProviderDirectFallbackTask;
  const runAcpTask = options.runAcpTask;
  const runCopilotTask = options.runCopilotTask;
  const shouldPreferLocalExecution = typeof options.shouldPreferLocalExecution === 'function'
    ? options.shouldPreferLocalExecution
    : (() => false);
  const canResolveLocalGoal = typeof options.canResolveLocalGoal === 'function'
    ? options.canResolveLocalGoal
    : (() => false);
  const buildLocalActions = typeof options.buildLocalActions === 'function'
    ? options.buildLocalActions
    : (() => []);
  const getMcpServers = typeof options.getMcpServers === 'function'
    ? options.getMcpServers
    : (() => []);
  const shouldUseProviderDirectFallback = typeof options.shouldUseProviderDirectFallback === 'function'
    ? options.shouldUseProviderDirectFallback
    : (() => false);
  const shouldUseLocalAgentFallback = typeof options.shouldUseLocalAgentFallback === 'function'
    ? options.shouldUseLocalAgentFallback
    : (() => false);

  function isContinuationGoal(goal) {
    const text = String(goal || '').trim().toLowerCase();
    if (!text) return false;
    return /^(continua|continuar|continúe|continua con|sigue|seguir|sigue con|retoma|retomar|debes continuar)\b/.test(text)
      || /^(hazlo|haz eso|solucionalo|soluciónalo|soluciona|arreglalo|arréglalo|arregla|corrigelo|corrígelo|corrige|aplicalo|aplícalo|aplica los cambios|realiza las modificaciones necesarias|ejecútalo|ejecutalo)\b/.test(text)
      || (/^(funciona|y ahora|siguiente paso)\b/.test(text) && text.split(/\s+/).length <= 4);
  }

  function buildContinuationPrompt(goal, sessionAgentState = null) {
    const state = sessionAgentState && typeof sessionAgentState === 'object' ? sessionAgentState : null;
    if (!state || !isContinuationGoal(goal)) {
      return String(goal || '').trim();
    }
    const lastGoal = String(state.lastUserGoal || '').trim();
    const lastSummary = String(state.lastAssistantSummary || '').trim();
    const taskId = String(state.lastTaskId || '').trim();
    const pieces = [
      String(goal || '').trim(),
      'Contexto de continuidad recuperado por Free JT7:',
      lastGoal ? `- Ultimo objetivo: ${lastGoal}` : '',
      lastSummary ? `- Ultimo resultado visible: ${lastSummary}` : '',
      taskId ? `- Ultima tarea: ${taskId}` : '',
      state.continuationHint ? `- Continuation hint: ${String(state.continuationHint).trim()}` : '',
    ].filter(Boolean);
    return pieces.join('\n');
  }

  function buildConversationEnvelope(task = {}, runtime = {}) {
    const originalGoal = String(task.goal || task.prompt || '').trim();
    const goal = buildContinuationPrompt(originalGoal, task.sessionAgentState || runtime.sessionAgentState || null);
    const reuseIncomingConversation = task.conversationRequest && goal === originalGoal;
    const capabilityHints = {
      selectedSkills: uniqueStrings((Array.isArray(task.selectedSkills || runtime.selectedSkills)
        ? (task.selectedSkills || runtime.selectedSkills)
        : []).map(normalizeSkillId)),
      mcpServers: normalizeMcpServers(getMcpServers(task, runtime)).map((item) => item.id),
      localOperations: inferLocalOperations(goal),
      plannedActions: summarizePlannedActions(buildLocalDispatchPlan(goal, task, runtime)),
      runtimeBackend: String(task.runtimeBackend || runtime.runtimeBackend || 'auto').trim().toLowerCase() || 'auto',
      provider: String(task.provider || runtime.defaultProvider || '').trim(),
      model: String(task.model || runtime.defaultModel || '').trim(),
      dispatchTarget: String(task.runtimeBackend || runtime.runtimeBackend || '').trim().toLowerCase().startsWith('acp:')
        ? 'acp-harness-request'
        : shouldPreferLocalExecution(goal)
          ? 'local-agent-runtime'
          : String(task.runtimeBackend || runtime.runtimeBackend || '').trim().toLowerCase() === 'freejt7'
            ? 'freejt7-owned-runtime'
          : 'openclaw-agent-runtime',
    };
    const conversationRequest = reuseIncomingConversation ? task.conversationRequest : buildConversationRequest({
      prompt: goal,
      history: task.chatHistorySnapshot || task.historySnapshot || task.history || [],
      sessionTitle: task.sessionTitle || runtime.sessionTitle || '',
      workspacePath: runtime.workspacePath || getWorkspacePath(),
      channel: 'control-panel',
      intake: task.intake || runtime.intake || null,
      selectedSkills: task.selectedSkills || runtime.selectedSkills || [],
      capabilities: capabilityHints,
    });
    return {
      goal,
      conversationRequest,
      serializedGoal: serializeConversationRequest(conversationRequest),
    };
  }

  function requireWorkspace(kind) {
    const workspacePath = String(getWorkspacePath() || '').trim();
    if (!workspacePath) {
      throw new Error(`Free JT7: abre un workspace antes de usar ${kind} desde el panel.`);
    }
    return workspacePath;
  }

  function buildAgentOptions(goal, taskContext = {}) {
    const effectiveProvider = getProviderConfig();
    return {
      goal,
      serializedConversationGoal: String(taskContext?.serializedConversationGoal || '').trim(),
      workspacePath: requireWorkspace('el modo agente'),
      runtimeRoot: String(taskContext?.runtimeRoot || options.runtimeRoot || '').trim(),
      provider: String(taskContext?.provider || effectiveProvider.provider || '').trim(),
      model: String(taskContext?.model || effectiveProvider.model || '').trim(),
      runtimeBackend: String(taskContext?.runtimeBackend || 'auto').trim().toLowerCase(),
      authProfile: String(taskContext?.authProfile || 'default').trim(),
      policyProfile: String(taskContext?.policyProfile || 'coding').trim(),
      fallbackProviders: Array.isArray(taskContext?.fallbackProviders) ? taskContext.fallbackProviders : [],
      sessionId: String(taskContext?.sessionId || '').trim(),
      runId: String(taskContext?.runId || '').trim(),
      secretStorage: taskContext?.secretStorage || context.secrets,
      conversationRequest: taskContext?.conversationRequest || null,
      selectedSkills: Array.isArray(taskContext?.selectedSkills) ? taskContext.selectedSkills : [],
      intake: taskContext?.intake || null,
    };
  }

  function buildLocalDispatchPlan(goal, taskContext = {}, routePlan = {}) {
    const workspacePath = String(taskContext.workspacePath || getWorkspacePath() || '').trim();
    const planningOptions = {
      ...taskContext,
      workspacePath,
      runtimeBackend: routePlan.runtimeBackend || taskContext.runtimeBackend || 'local',
      provider: routePlan.provider || taskContext.provider || '',
      model: routePlan.model || taskContext.model || '',
    };
    const planned = Array.isArray(buildLocalActions(goal, planningOptions))
      ? buildLocalActions(goal, planningOptions)
      : [];
    return planned.filter(Boolean);
  }

  function summarizePlannedActions(actions = []) {
    return actions.map((action) => {
      const type = String(action?.type || '').trim();
      if (!type) return '';
      if (type === 'read') return `read:${String(action.path || '').trim()}`;
      if (type === 'write') return `write:${String(action.path || '').trim()}`;
      if (type === 'mkdir') return `mkdir:${String(action.path || '').trim()}`;
      if (type === 'delete') return `delete:${String(action.path || '').trim()}`;
      if (type === 'inspect_path') return `inspect:${String(action.path || '').trim()}`;
      if (type === 'exec') return `exec:${String(action.commandLine || action.command || '').trim()}`;
      if (type === 'verify') return `verify:${[action.command, ...(Array.isArray(action.args) ? action.args : [])].filter(Boolean).join(' ')}`;
      if (type === 'system_install') return `system_install:${String(action.package || '').trim()}`;
      return type;
    }).filter(Boolean);
  }

  function inferLocalOperations(goal) {
    const text = String(goal || '').toLowerCase();
    return uniqueStrings([
      /\b(crea|crear|mkdir|carpeta|directorio)\b/.test(text) ? 'filesystem.mkdir' : '',
      /\b(borra|borrar|elimina|eliminar|delete|remove|rm)\b/.test(text) ? 'filesystem.delete' : '',
      /\b(lee|read|revisa|inspecciona|lista|ls|archivo|ruta|directorio)\b/.test(text) ? 'filesystem.read' : '',
      /\b(edita|edit|escribe|write|patch|parche)\b/.test(text) ? 'filesystem.write' : '',
      /\b(ejecuta|corre|run|bash|shell|comando)\b/.test(text) ? 'shell.exec' : '',
      /\b(build|test|prueba|verifica|lint|doctor|diagnost)\b/.test(text) ? 'shell.verify' : '',
      /\b(instala|install)\b/.test(text) ? 'system.install' : '',
      /\bgit\b/.test(text) ? 'git' : '',
    ]);
  }

  function buildCapabilityPlan(goal, taskContext = {}, routePlan = {}) {
    const skillIds = uniqueStrings((Array.isArray(taskContext?.selectedSkills) ? taskContext.selectedSkills : []).map(normalizeSkillId));
    const localOperations = inferLocalOperations(goal);
    const plannedActions = buildLocalDispatchPlan(goal, taskContext, routePlan);
    const mcpServers = normalizeMcpServers(getMcpServers(taskContext, routePlan));
    const mcpTools = inferNativeMcpTools(goal, mcpServers);
    let toolMode = 'provider-only';
    if (routePlan.primaryRoute === 'local-agent') {
      toolMode = 'local-tools';
    } else if (String(routePlan.primaryRoute || '').startsWith('acp:')) {
      toolMode = 'acp-harness';
    } else if (routePlan.primaryRoute === 'freejt7-agent') {
      toolMode = 'agent-owned';
    } else if (routePlan.primaryRoute === 'openclaw-agent') {
      toolMode = 'agent-backends';
    } else if (routePlan.primaryRoute === 'copilot-agent') {
      toolMode = 'copilot-legacy';
    }
    const dispatchTarget = routePlan.primaryRoute === 'local-agent'
      ? 'local-agent-runtime'
      : String(routePlan.primaryRoute || '').startsWith('acp:')
        ? 'acp-harness-request'
        : routePlan.primaryRoute === 'freejt7-agent'
          ? 'freejt7-owned-runtime'
        : routePlan.primaryRoute === 'openclaw-agent'
          ? 'openclaw-agent-runtime'
          : routePlan.primaryRoute === 'copilot-agent'
            ? 'copilot-legacy-runtime'
            : 'provider-runtime';
    const skillDispatch = skillIds.map((id) => ({
      id,
      activationPath: 'task.selectedSkills',
      dispatchTarget: 'conversation-context',
      providerIndependent: true,
    }));
    const mcpDispatch = mcpServers.map((server) => ({
      id: server.id,
      transport: server.transport,
      enabled: server.enabled !== false,
      activationPath: 'runtime.mcpSnapshot',
      dispatchTarget,
      providerIndependent: true,
    }));
    const nativeToolDispatch = mcpTools.map((tool) => ({
      family: tool.family,
      reason: tool.reason,
      activationPath: 'runtime.mcpSnapshot',
      dispatchTarget,
      providerIndependent: true,
    }));
    const dispatchTrace = [
      ...skillDispatch.map((entry) => `skill:${entry.id}->${entry.dispatchTarget}`),
      ...mcpDispatch.map((entry) => `mcp:${entry.id}->${entry.dispatchTarget}`),
      ...nativeToolDispatch.map((entry) => `mcp-tool:${entry.family}->${entry.dispatchTarget}`),
      ...summarizePlannedActions(plannedActions).map((entry) => `native-tool:${entry}->${dispatchTarget}`),
    ];
    return {
      toolMode,
      controlPlaneOwner: agentFacade.providerId,
      localCapable: Boolean(routePlan.localCapable),
      deterministicLocal: Boolean(routePlan.deterministicLocal),
      localOperations,
      plannedActions: summarizePlannedActions(plannedActions),
      selectedSkills: skillIds,
      skillDispatch,
      mcpServers,
      nativeMcpTools: nativeToolDispatch,
      intakeDefined: Boolean(taskContext?.intake),
      dispatchOwnedByRuntime: plannedActions.length > 0,
      backendHarness: routePlan.primaryRoute === 'openclaw-agent'
        ? 'openclaw'
        : routePlan.primaryRoute === 'freejt7-agent'
          ? 'freejt7-owned'
          : '',
      backendProvider: String(routePlan.provider || taskContext?.provider || '').trim(),
      backendModel: String(routePlan.model || taskContext?.model || '').trim(),
      backendFallbacks: Array.isArray(routePlan.fallbackOrder) ? routePlan.fallbackOrder.slice() : [],
      dispatch: {
        owner: 'freejt7-agent-runtime',
        providerIndependent: true,
        dispatchTarget,
        activationPath: 'runtime.capabilityPlan',
        trace: dispatchTrace,
      },
    };
  }

  function finalizePlan(basePlan, goal, taskContext = {}) {
    return {
      ...basePlan,
      capabilityPlan: buildCapabilityPlan(goal, taskContext, basePlan),
    };
  }

  function planTaskExecution(goal, taskContext = {}) {
    const agentOptions = buildAgentOptions(goal, taskContext);
    const runtimeBackend = agentOptions.runtimeBackend;
    const provider = agentOptions.provider;
    const model = agentOptions.model;
    const localCapable = canResolveLocalGoal(goal);
    const deterministicLocal = shouldPreferLocalExecution(goal);

    if (runtimeBackend === 'local') {
      return finalizePlan({
        primaryRoute: 'local-agent',
        runtimeBackend: 'local',
        provider: provider || 'local',
        model: model || 'freejt7-local-tools',
        localCapable: true,
        deterministicLocal,
        fallbackOrder: [],
        reason: 'runtimeBackend=local',
      }, goal, taskContext);
    }

    if (runtimeBackend.startsWith('acp:')) {
      return finalizePlan({
        primaryRoute: runtimeBackend,
        runtimeBackend,
        provider,
        model,
        localCapable,
        deterministicLocal,
        fallbackOrder: localCapable ? ['local-agent'] : [],
        reason: 'runtimeBackend=acp',
      }, goal, taskContext);
    }

    if (runtimeBackend === 'freejt7') {
      if (deterministicLocal) {
        return finalizePlan({
          primaryRoute: 'local-agent',
          runtimeBackend: 'local',
          provider: 'local',
          model: 'freejt7-local-tools',
          localCapable: true,
          deterministicLocal: true,
          fallbackOrder: [],
          reason: 'goal-resoluble-localmente',
        }, goal, taskContext);
      }
      const fallbackOrder = [];
      if (typeof runOpenClawAgentTask === 'function') {
        fallbackOrder.push('openclaw-agent');
      }
      if (localCapable) {
        fallbackOrder.push('local-agent');
      }
      return finalizePlan({
        primaryRoute: 'freejt7-agent',
        runtimeBackend: 'freejt7',
        provider,
        model,
        localCapable,
        deterministicLocal: false,
        fallbackOrder,
        reason: 'runtimeBackend=freejt7',
      }, goal, taskContext);
    }

    if (provider && provider !== 'copilot') {
      if (deterministicLocal) {
        return finalizePlan({
          primaryRoute: 'local-agent',
          runtimeBackend: 'local',
          provider: 'local',
          model: 'freejt7-local-tools',
          localCapable: true,
          deterministicLocal: true,
          fallbackOrder: [],
          reason: 'goal-resoluble-localmente',
        }, goal, taskContext);
      }
      const fallbackOrder = [];
      if (localCapable) {
        fallbackOrder.push('local-agent');
      }
      if (typeof runProviderDirectFallbackTask === 'function') {
        fallbackOrder.push('provider-direct');
      }
      return finalizePlan({
        primaryRoute: 'openclaw-agent',
        runtimeBackend: 'openclaw',
        provider,
        model,
        localCapable,
        deterministicLocal: false,
        fallbackOrder,
        reason: 'provider-externo-agent',
      }, goal, taskContext);
    }

    return finalizePlan({
      primaryRoute: 'copilot-agent',
      runtimeBackend: 'copilot',
      provider: 'copilot',
      model: '',
      localCapable,
      deterministicLocal,
      fallbackOrder: localCapable ? ['local-agent'] : [],
      reason: 'compatibilidad-copilot-legado',
    }, goal, taskContext);
  }

  function withExecutionPlan(result, plan, extraRouteMeta = {}, taskContext = {}) {
    const baseRouteMeta = result?.raw?.routeMeta && typeof result.raw.routeMeta === 'object'
      ? result.raw.routeMeta
      : result?.routeMeta && typeof result.routeMeta === 'object'
        ? result.routeMeta
        : {};
    const backend = buildSubordinateBackendDescriptor({
      executionRoute: result?.executionRoute || result?.raw?.executionRoute || plan.primaryRoute,
      primaryRoute: plan.primaryRoute,
      runtimeBackend: extraRouteMeta.runtimeBackend || baseRouteMeta.runtimeBackend || plan.runtimeBackend,
      provider: result?.provider || plan.provider || taskContext.provider,
      model: result?.model || plan.model || taskContext.model,
      authProfile: taskContext.authProfile || baseRouteMeta.authProfile || 'default',
      fallbackSelected: extraRouteMeta.fallbackSelected || baseRouteMeta.fallbackSelected || baseRouteMeta.fallback || '',
    });
    const shouldMaskVisibleProvider = backend.kind === 'openclaw-harness' || backend.kind === 'provider-direct';
    const routeMeta = {
      ...cloneJson(baseRouteMeta),
      executionPlan: cloneJson(plan),
      controlPlaneOwner: agentFacade.providerId,
      backend,
      backendSubordinated: shouldMaskVisibleProvider || Boolean(isExternalProvider(backend.provider)),
      visibleProvider: shouldMaskVisibleProvider ? agentFacade.providerId : String(result?.provider || '').trim(),
      visibleModel: shouldMaskVisibleProvider ? agentFacade.modelId : String(result?.model || '').trim(),
      ...cloneJson(extraRouteMeta),
    };
    const visibleProvider = shouldMaskVisibleProvider
      ? agentFacade.providerId
      : String(result?.provider || '').trim();
    const visibleModel = shouldMaskVisibleProvider
      ? agentFacade.modelId
      : String(result?.model || '').trim();
    return {
      ...result,
      provider: visibleProvider || result?.provider,
      model: visibleModel || result?.model,
      routeMeta,
      raw: {
        ...(result?.raw || {}),
        routeMeta,
      },
      run: result?.run ? {
        ...result.run,
        provider: visibleProvider || result.run.provider,
        model: visibleModel || result.run.model,
      } : result?.run,
    };
  }

  async function executeAgentTask(goal, taskContext = {}) {
    if (typeof runLocalAgentTask !== 'function' || typeof runOpenClawAgentTask !== 'function') {
      throw new Error('Free JT7 Agent Runtime no esta configurado correctamente.');
    }

    const agentOptions = buildAgentOptions(goal, taskContext);
    const plan = planTaskExecution(goal, taskContext);
    const provider = agentOptions.provider;
    const model = agentOptions.model;
    const runtimePlannedActions = buildLocalDispatchPlan(goal, taskContext, plan);

    if (plan.primaryRoute === 'local-agent') {
      const localResult = await runLocalAgentTask(context, output, {
        ...agentOptions,
        provider: plan.provider || provider || 'local',
        model: plan.model || model || 'freejt7-local-tools',
        runtimeBackend: plan.runtimeBackend,
        fallbackReason: plan.reason,
        actions: runtimePlannedActions,
        capabilityPlan: plan.capabilityPlan,
      });
      return withExecutionPlan(localResult, plan, {}, taskContext);
    }

    if (plan.primaryRoute.startsWith('acp:')) {
      if (typeof runAcpTask !== 'function') {
        throw new Error('Free JT7 Agent Runtime no tiene backend ACP configurado.');
      }
      const acpResult = await runAcpTask(context, output, {
        ...agentOptions,
        runtimeBackend: plan.primaryRoute,
        actions: runtimePlannedActions,
        capabilityPlan: plan.capabilityPlan,
      });
      return withExecutionPlan(acpResult, plan, {}, taskContext);
    }

    if (plan.primaryRoute === 'freejt7-agent') {
      if (typeof runOwnedAgentTask !== 'function') {
        throw new Error('Free JT7 Agent Runtime no tiene backend propio configurado.');
      }
      try {
        const ownResult = await runOwnedAgentTask(context, output, {
          ...agentOptions,
          goal: agentOptions.serializedConversationGoal || goal,
          runtimeBackend: 'freejt7',
          actions: runtimePlannedActions,
          capabilityPlan: plan.capabilityPlan,
        });
        return withExecutionPlan(ownResult, plan, {}, taskContext);
      } catch (error) {
        if (plan.fallbackOrder.includes('openclaw-agent') && shouldUseProviderDirectFallback(error)) {
          try {
            const openclawResult = await runOpenClawAgentTask(context, output, {
              ...agentOptions,
              goal: agentOptions.serializedConversationGoal || goal,
              runtimeBackend: 'openclaw',
            });
            return withExecutionPlan(openclawResult, plan, {
              fallbackSelected: 'openclaw-agent',
              fallbackReason: String(error?.message || error),
            }, taskContext);
          } catch (openclawError) {
            output.appendLine(`[freejt7-agent-runtime] fallback OpenClaw desde backend propio falló: ${String(openclawError?.message || openclawError)}`);
            if (plan.fallbackOrder.includes('local-agent') && shouldUseLocalAgentFallback(goal, openclawError, { forceForDeterministicGoal: true })) {
              const localResult = await runLocalAgentTask(context, output, {
                ...agentOptions,
                fallbackReason: String(openclawError?.message || openclawError),
                actions: runtimePlannedActions,
                capabilityPlan: plan.capabilityPlan,
              });
              return withExecutionPlan(localResult, plan, {
                fallbackSelected: 'local-agent',
                fallbackReason: String(openclawError?.message || openclawError),
              }, taskContext);
            }
            throw openclawError;
          }
        }
        if (!plan.fallbackOrder.includes('local-agent') || !shouldUseLocalAgentFallback(goal, error)) {
          throw error;
        }
        const localResult = await runLocalAgentTask(context, output, {
          ...agentOptions,
          fallbackReason: String(error?.message || error),
          actions: runtimePlannedActions,
          capabilityPlan: plan.capabilityPlan,
        });
        return withExecutionPlan(localResult, plan, {
          fallbackSelected: 'local-agent',
          fallbackReason: String(error?.message || error),
        }, taskContext);
      }
    }

    if (plan.primaryRoute === 'openclaw-agent') {
      try {
        const openclawResult = await runOpenClawAgentTask(context, output, {
          ...agentOptions,
          goal: agentOptions.serializedConversationGoal || goal,
        });
        return withExecutionPlan(openclawResult, plan, {}, taskContext);
      } catch (error) {
        if (plan.fallbackOrder.includes('local-agent') && shouldUseLocalAgentFallback(goal, error, { forceForDeterministicGoal: true })) {
          output.appendLine(`[freejt7-agent-runtime] fallback local prioritario por OpenClaw no disponible: ${String(error?.message || error)}`);
          const localResult = await runLocalAgentTask(context, output, {
            ...agentOptions,
            fallbackReason: String(error?.message || error),
            actions: runtimePlannedActions,
            capabilityPlan: plan.capabilityPlan,
          });
          return withExecutionPlan(localResult, plan, {
            fallbackSelected: 'local-agent',
            fallbackReason: String(error?.message || error),
          }, taskContext);
        }
        if (plan.fallbackOrder.includes('provider-direct') && shouldUseProviderDirectFallback(error) && typeof runProviderDirectFallbackTask === 'function') {
          try {
            const directResult = await runProviderDirectFallbackTask(context, output, {
              ...agentOptions,
              goal: agentOptions.serializedConversationGoal || goal,
              fallbackReason: String(error?.message || error),
              conversationRequest: taskContext?.conversationRequest || null,
            });
            return withExecutionPlan(directResult, plan, {
              fallbackSelected: 'provider-direct',
              fallbackReason: String(error?.message || error),
            }, taskContext);
          } catch (directError) {
            output.appendLine(`[freejt7-agent-runtime] fallback directo falló: ${String(directError?.message || directError)}`);
            if (plan.fallbackOrder.includes('local-agent') && shouldUseLocalAgentFallback(goal, error, { forceForDeterministicGoal: true })) {
              const localResult = await runLocalAgentTask(context, output, {
                ...agentOptions,
                fallbackReason: String(directError?.message || directError),
                actions: runtimePlannedActions,
                capabilityPlan: plan.capabilityPlan,
              });
              return withExecutionPlan(localResult, plan, {
                fallbackSelected: 'local-agent',
                fallbackReason: String(directError?.message || directError),
              }, taskContext);
            }
          }
        }
        if (!plan.fallbackOrder.includes('local-agent') || !shouldUseLocalAgentFallback(goal, error)) {
          throw error;
        }
        output.appendLine(`[freejt7-agent-runtime] fallback local por OpenClaw no disponible: ${String(error?.message || error)}`);
        const localResult = await runLocalAgentTask(context, output, {
          ...agentOptions,
          fallbackReason: String(error?.message || error),
          actions: runtimePlannedActions,
          capabilityPlan: plan.capabilityPlan,
        });
        return withExecutionPlan(localResult, plan, {
          fallbackSelected: 'local-agent',
          fallbackReason: String(error?.message || error),
        }, taskContext);
      }
    }

    if (typeof runCopilotTask !== 'function') {
      throw new Error('Free JT7 Agent Runtime no tiene ruta Copilot configurada.');
    }
    try {
      const copilotResult = await runCopilotTask(goal, taskContext);
      return withExecutionPlan(copilotResult, plan, {}, taskContext);
    } catch (error) {
      if (!plan.fallbackOrder.includes('local-agent') || !shouldUseLocalAgentFallback(goal, error)) {
        throw error;
      }
      output.appendLine(`[freejt7-agent-runtime] fallback local por Copilot no disponible: ${String(error?.message || error)}`);
      const localResult = await runLocalAgentTask(context, output, {
        goal,
        workspacePath: agentOptions.workspacePath,
        provider: 'local',
        model: 'freejt7-local-tools',
        fallbackReason: String(error?.message || error),
        actions: runtimePlannedActions,
        capabilityPlan: plan.capabilityPlan,
      });
      return withExecutionPlan(localResult, plan, {
        fallbackSelected: 'local-agent',
        fallbackReason: String(error?.message || error),
      }, taskContext);
    }
  }

  async function executeTask(task = {}, runtime = {}) {
    const envelope = buildConversationEnvelope(task, runtime);
    return executeAgentTask(envelope.goal, {
      ...task,
      ...runtime,
      workspacePath: runtime.workspacePath || getWorkspacePath(),
      conversationRequest: envelope.conversationRequest,
      serializedConversationGoal: envelope.serializedGoal,
    });
  }

  function getHealthStatus() {
    return {
      ok: true,
      runtimeKind: 'freejt7-agent-runtime',
      ownsFlow: true,
      continuityOwnedByRuntime: true,
      routePlanningOwnedByRuntime: true,
      capabilityPlanningOwnedByRuntime: true,
      backendSubordinationOwnedByRuntime: true,
      skillsOwnedByRuntime: true,
      mcpOwnedByRuntime: true,
      nativeToolsOwnedByRuntime: true,
      supports: {
        openclaw: typeof runOpenClawAgentTask === 'function',
        local: typeof runLocalAgentTask === 'function',
        providerDirect: typeof runProviderDirectFallbackTask === 'function',
        acp: typeof runAcpTask === 'function',
        copilot: typeof runCopilotTask === 'function',
      },
      checkedAt: new Date().toISOString(),
    };
  }

  return {
    executeAgentTask,
    executeTask,
    planTaskExecution,
    getHealthStatus,
  };
}

module.exports = {
  createFreeJt7AgentRuntime,
};

'use strict';

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const SAFE_COMMANDS = Object.freeze([
  {
    label: 'git status --short',
    command: 'git',
    args: ['status', '--short'],
  },
  {
    label: 'node --version',
    command: process.execPath,
    args: ['--version'],
  },
]);

const DEFAULT_MAX_READ_BYTES = 128 * 1024;
const DEFAULT_MAX_WRITE_BYTES = 256 * 1024;
const SAFE_VERIFY_COMMANDS = new Set(['git', 'node', 'npm']);
const SYSTEM_PACKAGES = Object.freeze({
  git: Object.freeze({
    binary: 'git',
    versionArgs: ['--version'],
    installers: Object.freeze({
      apt: { command: 'apt-get', args: ['install', '-y', 'git'] },
      dnf: { command: 'dnf', args: ['install', '-y', 'git'] },
      yum: { command: 'yum', args: ['install', '-y', 'git'] },
      pacman: { command: 'pacman', args: ['-S', '--noconfirm', 'git'] },
      apk: { command: 'apk', args: ['add', 'git'] },
      brew: { command: 'brew', args: ['install', 'git'] },
    }),
  }),
});

const COMMON_EXECUTABLE_DIRS = Object.freeze([
  '/usr/local/bin',
  '/usr/bin',
  '/bin',
  '/usr/sbin',
  '/sbin',
]);

const BLOCKED_EXEC_PATTERNS = [
  /\brm\s+-rf(?:\s+--no-preserve-root)?\s+\/(?:\s|$)/i,
  /\bshutdown\b/i,
  /\breboot\b/i,
  /\bpoweroff\b/i,
  /\bmkfs\b/i,
  /\bdd\s+if=/i,
  /:\(\)\s*\{/,
];

function truncate(text, max = 4000) {
  const value = String(text || '');
  return value.length > max ? `${value.slice(0, max)}\n...<truncated>` : value;
}

function extractFocusedText(goal) {
  const focused = extractFocusedGoal(goal);
  return focused || summarizeGoal(goal);
}

function canResolveLocalGoal(goal) {
  const raw = String(goal || '');
  const focused = String(extractFocusedText(goal) || '').toLowerCase();
  const fullText = `${focused}\n${raw.toLowerCase()}`;
  if (!focused) {
    return false;
  }
  if (isAgentAutonomyDiagnosticGoal(focused)) {
    return true;
  }
  const hasContinuationIntent = /^(continua|continuar|continúe|continua con|sigue|seguir|sigue con|retoma|retomar|debes continuar)\b/.test(focused);
  const hasOperationalContext = /solicitud actual:|ultimo objetivo:|continuation hint:|objetivo:|package\.json|readme|\.md\b|\.json\b|\.js\b|\.ts\b|\barchivo\b|\bruta\b|\bpath\b|\bworkspace\b|\brepositorio\b|\brepo\b|\bproyecto\b|\bbuild\b|\bbundle\b|\bcompil|\btest\b|\bprueba\b|\bverifica|\bverificaci|\blint\b|\binstala\b|\binstall\b|\bgit\b|\blee\b|\bread\b|\bescribe\b|\bwrite\b|\bedita\b|\bedit\b|\bparche\b|\bpatch\b|\bdiff\b|\blog\b|\bstatus\b|\bdoctor\b|\bdiagnost|\bcarpeta\b|\bdirectorio\b|\bmkdir\b|\bcrear\b|\bcrea\b|\blista\b|\bls\b|\binspecciona\b|\brevisa\b|\bskill\b|\btool\b|\bmcp\b|\bprovider\b|\bproveedor\b|\bmodel\b|\bmodelo\b|\bsettings\b|\bajustes\b|\bconfig\b|\bconfiguracion\b|\binterfaz\b|\bpanel\b|\baparece\b/i.test(fullText);
  if (/\b(hola|gracias)\b/.test(focused) && focused.split(/\s+/).length <= 4 && !hasOperationalContext) {
    return false;
  }
  if (/\bporque\b.*\bagente\b|\bpor que\b.*\bagente\b|\bno estas usando el agente\b/.test(focused)) {
    return false;
  }
  if (hasContinuationIntent) {
    return hasOperationalContext;
  }
  return hasOperationalContext;
}

function normalizeRelativePath(filePath) {
  return String(filePath || '').replace(/\\/g, '/').replace(/^\/+/, '').trim();
}

function resolveWorkspacePath(workspacePath, filePath) {
  const root = path.resolve(workspacePath || process.cwd());
  const relative = normalizeRelativePath(filePath);
  if (!relative || relative.includes('\0')) {
    throw new Error('Ruta de workspace invalida.');
  }
  const resolved = path.resolve(root, relative);
  const rootWithSep = root.endsWith(path.sep) ? root : `${root}${path.sep}`;
  if (resolved !== root && !resolved.startsWith(rootWithSep)) {
    throw new Error(`Ruta fuera del workspace bloqueada: ${filePath}`);
  }
  return { root, relative, resolved };
}

function getActionList(options = {}) {
  if (Array.isArray(options.actions)) {
    return options.actions.filter(Boolean);
  }

  const actions = [];
  for (const filePath of Array.isArray(options.readFiles) ? options.readFiles : []) {
    actions.push({ type: 'read', path: filePath });
  }
  for (const item of Array.isArray(options.writeFiles) ? options.writeFiles : []) {
    if (item && typeof item === 'object') {
      actions.push({ type: 'write', path: item.path, content: item.content });
    }
  }
  for (const item of Array.isArray(options.verificationCommands) ? options.verificationCommands : []) {
    actions.push({ type: 'verify', ...(typeof item === 'string' ? { command: item } : item) });
  }
  return actions;
}

function isSafeVerifySpec(spec = {}) {
  const command = String(spec.command || '').trim();
  const args = Array.isArray(spec.args) ? spec.args.map((item) => String(item)) : [];
  const base = path.basename(command).replace(/\.cmd$/i, '').replace(/\.exe$/i, '');
  if (!SAFE_VERIFY_COMMANDS.has(base) && command !== process.execPath) {
    return { ok: false, reason: `Comando no permitido para verificacion local: ${command || '(vacio)'}` };
  }
  if (base === 'node' || command === process.execPath) {
    if (args.some((arg) => ['-e', '--eval', '-p', '--print'].includes(arg))) {
      return { ok: false, reason: 'Node eval/print bloqueado en verificacion local.' };
    }
  }
  if (base === 'npm') {
    const first = args[0] || '';
    if (!['test', 'run', '--version', '-v'].includes(first)) {
      return { ok: false, reason: 'npm solo permite test/run/version en verificacion local.' };
    }
    if (first === 'run' && !args[1]) {
      return { ok: false, reason: 'npm run requiere nombre de script.' };
    }
  }
  if (base === 'git') {
    const first = args[0] || '';
    if (!['status', 'diff', 'rev-parse'].includes(first)) {
      return { ok: false, reason: 'git solo permite status/diff/rev-parse en verificacion local.' };
    }
  }
  return { ok: true, command, args };
}

function runVerificationCommand(spec, cwd) {
  const normalized = typeof spec === 'string' ? { command: spec, args: [] } : (spec || {});
  const safety = isSafeVerifySpec(normalized);
  if (!safety.ok) {
    return {
      command: String(normalized.command || '').trim(),
      exitCode: 1,
      blocked: true,
      output: safety.reason,
    };
  }
  return runSafeCommand({
    label: [safety.command, ...safety.args].filter(Boolean).join(' '),
    command: safety.command === 'node' ? process.execPath : safety.command,
    args: safety.command === 'node' ? safety.args : safety.args,
  }, cwd);
}

function readWorkspaceFile(workspacePath, action = {}) {
  const { relative, resolved } = resolveWorkspacePath(workspacePath, action.path || action.filePath);
  const stat = fs.statSync(resolved);
  if (!stat.isFile()) {
    throw new Error(`No es archivo legible: ${relative}`);
  }
  const maxBytes = Math.max(1, Number(action.maxBytes || DEFAULT_MAX_READ_BYTES));
  const fd = fs.openSync(resolved, 'r');
  try {
    const size = Math.min(stat.size, maxBytes);
    const buffer = Buffer.alloc(size);
    fs.readSync(fd, buffer, 0, size, 0);
    return {
      path: relative,
      bytes: stat.size,
      truncated: stat.size > maxBytes,
      content: buffer.toString('utf8'),
    };
  } finally {
    fs.closeSync(fd);
  }
}

function writeWorkspaceFile(workspacePath, action = {}) {
  const { relative, resolved } = resolveWorkspacePath(workspacePath, action.path || action.filePath);
  const content = String(action.content ?? '');
  const maxBytes = Math.max(1, Number(action.maxBytes || DEFAULT_MAX_WRITE_BYTES));
  if (Buffer.byteLength(content, 'utf8') > maxBytes) {
    throw new Error(`Escritura bloqueada por tamano maximo: ${relative}`);
  }
  const exists = fs.existsSync(resolved);
  const previous = exists ? fs.readFileSync(resolved, 'utf8') : null;
  if (exists && action.overwrite === false) {
    throw new Error(`Escritura bloqueada porque el archivo existe: ${relative}`);
  }
  fs.mkdirSync(path.dirname(resolved), { recursive: true });
  fs.writeFileSync(resolved, content, 'utf8');
  const readback = fs.readFileSync(resolved, 'utf8');
  if (readback !== content) {
    if (previous !== null) {
      fs.writeFileSync(resolved, previous, 'utf8');
    }
    throw new Error(`Readback de escritura fallo: ${relative}`);
  }
  return {
    path: relative,
    bytes: Buffer.byteLength(content, 'utf8'),
    created: !exists,
    verified: true,
  };
}

function resolveFlexiblePath(workspacePath, targetPath, options = {}) {
  const raw = String(targetPath || '').trim();
  if (!raw || raw.includes('\0')) {
    throw new Error('Ruta invalida.');
  }
  if (path.isAbsolute(raw)) {
    const resolved = path.resolve(raw);
    if (!options.allowAbsolute) {
      throw new Error(`Ruta absoluta bloqueada: ${raw}`);
    }
    return {
      root: '',
      relative: raw,
      resolved,
      absolute: true,
    };
  }
  return {
    ...resolveWorkspacePath(workspacePath, raw),
    absolute: false,
  };
}

function createDirectory(workspacePath, action = {}) {
  const target = resolveFlexiblePath(workspacePath, action.path || action.dirPath, {
    allowAbsolute: action.allowAbsolute !== false,
  });
  const existed = fs.existsSync(target.resolved);
  if (existed && !fs.statSync(target.resolved).isDirectory()) {
    throw new Error(`La ruta existe pero no es un directorio: ${target.relative}`);
  }
  fs.mkdirSync(target.resolved, { recursive: true });
  const stat = fs.statSync(target.resolved);
  if (!stat.isDirectory()) {
    throw new Error(`No se pudo verificar el directorio creado: ${target.relative}`);
  }
  return {
    path: target.absolute ? target.resolved : target.relative,
    created: !existed,
    verified: true,
  };
}

function deletePath(workspacePath, action = {}) {
  const target = resolveFlexiblePath(workspacePath, action.path || action.dirPath || action.filePath, {
    allowAbsolute: action.allowAbsolute !== false,
  });
  if (!fs.existsSync(target.resolved)) {
    return {
      path: target.absolute ? target.resolved : target.relative,
      removed: false,
      missing: true,
      kind: 'missing',
    };
  }
  const stat = fs.statSync(target.resolved);
  const kind = stat.isDirectory() ? 'dir' : 'file';
  const recursive = action.recursive !== false;
  if (kind === 'dir' && !recursive) {
    throw new Error(`Borrado bloqueado: ${target.relative} es directorio y recursive=false.`);
  }
  fs.rmSync(target.resolved, { recursive, force: false });
  return {
    path: target.absolute ? target.resolved : target.relative,
    removed: true,
    missing: false,
    kind,
  };
}

function inspectPath(workspacePath, action = {}) {
  const target = resolveFlexiblePath(workspacePath, action.path || action.dirPath || action.filePath, {
    allowAbsolute: action.allowAbsolute !== false,
  });
  const exists = fs.existsSync(target.resolved);
  if (!exists) {
    return {
      path: target.absolute ? target.resolved : target.relative,
      exists: false,
      kind: 'missing',
      entries: [],
    };
  }
  const stat = fs.statSync(target.resolved);
  if (stat.isDirectory()) {
    const entries = fs.readdirSync(target.resolved, { withFileTypes: true })
      .slice(0, 20)
      .map((entry) => `${entry.isDirectory() ? 'dir' : entry.isFile() ? 'file' : 'other'}:${entry.name}`);
    return {
      path: target.absolute ? target.resolved : target.relative,
      exists: true,
      kind: 'dir',
      entries,
    };
  }
  return {
    path: target.absolute ? target.resolved : target.relative,
    exists: true,
    kind: 'file',
    entries: [],
  };
}

function executeLocalActions(workspacePath, options = {}) {
  const actions = getActionList(options);
  const reads = [];
  const writes = [];
  const dirActions = [];
  const deleteActions = [];
  const inspections = [];
  const verificationResults = [];
  const execResults = [];
  const systemActions = [];
  const failures = [];

  for (const action of actions) {
    const type = String(action.type || action.kind || '').trim().toLowerCase();
    try {
      if (type === 'read' || type === 'readfile') {
        reads.push(readWorkspaceFile(workspacePath, action));
        continue;
      }
      if (type === 'write' || type === 'writefile') {
        writes.push(writeWorkspaceFile(workspacePath, action));
        continue;
      }
      if (type === 'mkdir' || type === 'create_dir' || type === 'create_directory') {
        dirActions.push(createDirectory(workspacePath, action));
        continue;
      }
      if (type === 'delete' || type === 'remove' || type === 'rm' || type === 'delete_path') {
        deleteActions.push(deletePath(workspacePath, action));
        continue;
      }
      if (type === 'inspect_path' || type === 'list_path' || type === 'stat_path') {
        inspections.push(inspectPath(workspacePath, action));
        continue;
      }
      if (type === 'exec' || type === 'shell' || type === 'bash') {
        execResults.push(runExecCommand(workspacePath, action));
        continue;
      }
      if (type === 'verify' || type === 'verification' || type === 'command') {
        verificationResults.push(runVerificationCommand(action, workspacePath));
        continue;
      }
      if (type === 'system_install' || type === 'install_package') {
        systemActions.push(installSystemPackage(workspacePath, action));
        continue;
      }
      if (type) {
        failures.push({ type, error: `Accion local no soportada: ${type}` });
      }
    } catch (error) {
      failures.push({
        type: type || 'unknown',
        path: String(action.path || action.filePath || ''),
        error: String(error && error.message ? error.message : error),
      });
    }
  }

  return { reads, writes, dirActions, deleteActions, inspections, verificationResults, execResults, systemActions, failures };
}

function listWorkspace(workspacePath, maxEntries = 80) {
  const root = path.resolve(workspacePath || process.cwd());
  const entries = fs.readdirSync(root, { withFileTypes: true })
    .filter((entry) => !['.git', 'node_modules', 'dist'].includes(entry.name))
    .slice(0, maxEntries)
    .map((entry) => ({
      name: entry.name,
      kind: entry.isDirectory() ? 'dir' : entry.isFile() ? 'file' : 'other',
    }));
  return {
    root,
    entries,
    files: entries.filter((entry) => entry.kind === 'file').length,
    dirs: entries.filter((entry) => entry.kind === 'dir').length,
  };
}

function readPackageSummary(workspacePath) {
  const packagePath = path.join(path.resolve(workspacePath || process.cwd()), 'package.json');
  if (!fs.existsSync(packagePath)) {
    return null;
  }
  try {
    const pkg = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
    return {
      name: pkg.name || '',
      version: pkg.version || '',
      scripts: Object.keys(pkg.scripts || {}).sort(),
    };
  } catch (error) {
    return { error: String(error && error.message ? error.message : error) };
  }
}

function runSafeCommand(spec, cwd) {
  try {
    const result = spawnSync(spec.command, spec.args, {
      cwd,
      encoding: 'utf8',
      timeout: 15000,
      windowsHide: true,
    });
    return {
      command: spec.label,
      exitCode: typeof result.status === 'number' ? result.status : 1,
      output: truncate(`${result.stdout || ''}${result.stderr || ''}`.trim(), 2000),
    };
  } catch (error) {
    return {
      command: spec.label,
      exitCode: 1,
      output: String(error && error.message ? error.message : error),
    };
  }
}

function findExecutable(command, cwd) {
  const lookup = spawnSync(process.platform === 'win32' ? 'where' : 'which', [command], {
    cwd,
    encoding: 'utf8',
    timeout: 5000,
    windowsHide: true,
  });
  let resolvedPath = String(lookup.stdout || '')
    .split(/\r?\n/)
    .map((line) => line.trim())
    .find(Boolean) || '';
  if (!resolvedPath && process.platform !== 'win32') {
    const home = process.env.HOME || '';
    const candidates = [
      path.join(home, '.local', 'bin', command),
      path.join(home, '.local', 'nodejs', 'current', 'bin', command),
      ...COMMON_EXECUTABLE_DIRS.map((dir) => path.join(dir, command)),
    ];
    resolvedPath = candidates.find((candidate) => {
      try {
        return Boolean(candidate) && fs.existsSync(candidate) && fs.statSync(candidate).isFile();
      } catch (_) {
        return false;
      }
    }) || '';
  }
  if (!resolvedPath && process.platform !== 'win32') {
    const shellLookup = spawnSync('bash', ['-lc', `command -v ${command}`], {
      cwd,
      encoding: 'utf8',
      timeout: 5000,
      windowsHide: true,
    });
    resolvedPath = String(shellLookup.stdout || '')
      .split(/\r?\n/)
      .map((line) => line.trim())
      .find(Boolean) || '';
  }
  return {
    ok: Boolean(resolvedPath),
    path: resolvedPath,
    output: truncate(`${lookup.stdout || ''}${lookup.stderr || ''}`.trim(), 1000),
  };
}

function findAvailablePackageManager(cwd) {
  const managers = [
    { key: 'apt', command: 'apt-get' },
    { key: 'dnf', command: 'dnf' },
    { key: 'yum', command: 'yum' },
    { key: 'pacman', command: 'pacman' },
    { key: 'apk', command: 'apk' },
    { key: 'brew', command: 'brew' },
  ];
  for (const manager of managers) {
    if (findExecutable(manager.command, cwd).ok) {
      return manager.key;
    }
  }
  return '';
}

function runSystemInstallCommand(installer, cwd) {
  const isRoot = typeof process.getuid === 'function' && process.getuid() === 0;
  let command = installer.command;
  let args = installer.args.slice();

  if (!isRoot && command !== 'brew') {
    if (!findExecutable('sudo', cwd).ok) {
      return {
        command: [command, ...args].join(' '),
        exitCode: 1,
        blocked: true,
        output: 'Instalacion bloqueada: se requieren privilegios de administrador y sudo no esta disponible.',
      };
    }
    command = 'sudo';
    args = ['-n', installer.command, ...installer.args];
  }

  return runSafeCommand({
    label: [command, ...args].join(' '),
    command,
    args,
  }, cwd);
}

function classifyExecCommand(commandLine) {
  const text = String(commandLine || '').trim();
  if (!text) {
    return { ok: false, reason: 'Comando vacio para exec local.' };
  }
  for (const pattern of BLOCKED_EXEC_PATTERNS) {
    if (pattern.test(text)) {
      return { ok: false, reason: `Comando bloqueado por riesgo: ${text}` };
    }
  }
  return { ok: true, commandLine: text };
}

function runExecCommand(workspacePath, action = {}) {
  const cwd = path.resolve(String(action.cwd || workspacePath || process.cwd()).trim() || process.cwd());
  const commandLine = String(action.commandLine || action.command || '').trim();
  const classified = classifyExecCommand(commandLine);
  if (!classified.ok) {
    return {
      command: commandLine || '(vacio)',
      exitCode: 1,
      blocked: true,
      output: classified.reason,
    };
  }
  const timeout = Math.max(1_000, Math.min(120_000, Number(action.timeoutMs || 30_000)));
  try {
    const result = process.platform === 'win32'
      ? spawnSync('cmd', ['/c', classified.commandLine], { cwd, encoding: 'utf8', timeout, windowsHide: true })
      : spawnSync('bash', ['-lc', classified.commandLine], { cwd, encoding: 'utf8', timeout, windowsHide: true });
    return {
      command: classified.commandLine,
      exitCode: typeof result.status === 'number' ? result.status : 1,
      blocked: false,
      output: truncate(`${result.stdout || ''}${result.stderr || ''}`.trim(), 4000),
    };
  } catch (error) {
    return {
      command: classified.commandLine,
      exitCode: 1,
      blocked: false,
      output: String(error?.message || error),
    };
  }
}

function installSystemPackage(workspacePath, action = {}) {
  const cwd = path.resolve(workspacePath || process.cwd());
  const packageName = String(action.package || action.name || '').trim().toLowerCase();
  const spec = SYSTEM_PACKAGES[packageName];

  if (!spec) {
    return {
      package: packageName || '(vacio)',
      status: 'blocked',
      changed: false,
      output: `Paquete no soportado por el runtime local: ${packageName || '(vacio)'}`,
    };
  }

  const before = findExecutable(spec.binary, cwd);
  if (before.ok) {
    const version = runSafeCommand({
      label: `${before.path || spec.binary} ${spec.versionArgs.join(' ')}`,
      command: before.path || spec.binary,
      args: spec.versionArgs,
    }, cwd);
    return {
      package: packageName,
      status: 'already_installed',
      changed: false,
      binaryPath: before.path,
      command: version.command,
      exitCode: version.exitCode,
      output: version.output || before.output,
    };
  }

  const managerKey = findAvailablePackageManager(cwd);
  const installer = managerKey ? spec.installers[managerKey] : null;
  if (!installer) {
    return {
      package: packageName,
      status: 'blocked',
      changed: false,
      output: 'Instalacion bloqueada: no se encontro un gestor de paquetes soportado.',
    };
  }

  const installResult = runSystemInstallCommand(installer, cwd);
  const after = findExecutable(spec.binary, cwd);
  const version = after.ok
    ? runSafeCommand({
      label: `${after.path || spec.binary} ${spec.versionArgs.join(' ')}`,
      command: after.path || spec.binary,
      args: spec.versionArgs,
    }, cwd)
    : null;

  return {
    package: packageName,
    status: after.ok ? 'installed' : (installResult.blocked ? 'blocked' : 'failed'),
    changed: after.ok,
    manager: managerKey || 'unknown',
    binaryPath: after.path,
    command: installResult.command,
    exitCode: installResult.exitCode,
    blocked: Boolean(installResult.blocked),
    output: version?.output || installResult.output,
  };
}

function summarizeGoal(goal) {
  return String(goal || '').replace(/\s+/g, ' ').trim();
}

function extractFocusedGoal(goal) {
  const raw = String(goal || '');
  const currentRequestMatches = Array.from(raw.matchAll(/Solicitud actual:\s*([^\r\n]+)/gi));
  const latestCurrentRequest = currentRequestMatches.length
    ? currentRequestMatches[currentRequestMatches.length - 1][1]
    : '';
  if (latestCurrentRequest) {
    return summarizeGoal(latestCurrentRequest);
  }

  const objectiveMatches = Array.from(raw.matchAll(/Objetivo solicitado:\s*([^\r\n]+)/gi));
  const latestObjective = objectiveMatches.length
    ? objectiveMatches[objectiveMatches.length - 1][1]
    : '';
  if (latestObjective) {
    return summarizeGoal(latestObjective);
  }

  const compact = summarizeGoal(raw);
  if (!compact) {
    return '';
  }
  if (compact.length > 320) {
    return `${compact.slice(0, 320)}...`;
  }
  return compact;
}

function parseReferencedPaths(goal) {
  const matches = String(goal || '').match(/(?:[A-Za-z0-9_./-]+\.[A-Za-z0-9_-]+)/g) || [];
  return Array.from(new Set(matches.map((item) => normalizeRelativePath(item)).filter(Boolean)));
}

function parseAbsolutePathCandidates(goal) {
  const source = String(goal || '');
  const matches = source.match(/\/[^\n"`]+/g) || [];
  return Array.from(new Set(matches
    .map((item) => item.replace(/[),.;:!?]+$/g, '').trim())
    .filter((item) => item.startsWith('/'))));
}

function parseCreateDirectoryIntent(goal) {
  const source = String(goal || '');
  const patterns = [
    /directorio siguiente:\s*(\/[^\n]+?)\s*el nombre de la car\w*ta\s+sera\s+([^\n]+)/i,
    /directorio siguiente:\s*(\/[^\n]+?)\s*el nombre de la car\w*ta\s+será\s+([^\n]+)/i,
    /(?:crea|crear|cree|crees|quecrees|mkdir)\s+(?:una\s+)?(?:carpeta|directorio).+?(?:en|dentro de)\s*(\/[^\n]+?)\s*(?:con nombre|llamada|que se llame|nombrada)\s+([^\n]+)/i,
  ];
  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (!match) continue;
    const parent = String(match[1] || '').trim().replace(/[),.;:!?]+$/g, '');
    const name = String(match[2] || '').trim().replace(/^[`"' ]+|[`"',.;:!? ]+$/g, '');
    if (path.isAbsolute(parent) && name) {
      return path.join(parent, name);
    }
  }
  const directTarget = source.match(/crea(?:r)?\s+(?:una\s+)?(?:carpeta|directorio)\s+(\/[^\n]+)/i);
  if (directTarget) {
    return String(directTarget[1] || '').trim().replace(/[),.;:!?]+$/g, '');
  }
  return '';
}

function hasCreateDirectoryIntent(goal) {
  const source = String(goal || '');
  return /\b(crea|crear|cree|crees|quecrees|mkdir)\b/.test(source)
    && /\b(carpeta|directorio)\b/.test(source);
}

function isIncompleteCreateDirectoryIntent(goal) {
  const focusedGoal = extractFocusedText(goal);
  if (!hasCreateDirectoryIntent(focusedGoal)) {
    return false;
  }
  return !parseCreateDirectoryIntent(focusedGoal);
}

function fileExistsInWorkspace(workspacePath, relativePath) {
  try {
    const { resolved } = resolveWorkspacePath(workspacePath, relativePath);
    return fs.existsSync(resolved) && fs.statSync(resolved).isFile();
  } catch {
    return false;
  }
}

function addHeuristicVerify(actions, addedCommands, command, args) {
  const key = [command, ...(args || [])].join(' ');
  if (addedCommands.has(key)) {
    return;
  }
  addedCommands.add(key);
  actions.push({ type: 'verify', command, args });
}

function inferHeuristicActions(workspacePath, goal, packageSummary, options = {}) {
  if (getActionList(options).length > 0) {
    return [];
  }

  const focusedGoal = extractFocusedText(goal);
  const normalizedGoal = String(focusedGoal || '').toLowerCase();
  const actions = [];
  const addedReads = new Set();
  const addedCommands = new Set();
  const referencedPaths = parseReferencedPaths(focusedGoal);
  for (const relativePath of referencedPaths) {
    if (!addedReads.has(relativePath) && fileExistsInWorkspace(workspacePath, relativePath)) {
      addedReads.add(relativePath);
      actions.push({ type: 'read', path: relativePath });
    }
  }

  if (normalizedGoal.includes('package.json') && fileExistsInWorkspace(workspacePath, 'package.json') && !addedReads.has('package.json')) {
    addedReads.add('package.json');
    actions.push({ type: 'read', path: 'package.json' });
  }
  if ((normalizedGoal.includes('readme') || normalizedGoal.includes('README')) && fileExistsInWorkspace(workspacePath, 'README.md') && !addedReads.has('README.md')) {
    addedReads.add('README.md');
    actions.push({ type: 'read', path: 'README.md' });
  }

  const scripts = Array.isArray(packageSummary?.scripts) ? packageSummary.scripts : [];
  const wantsValidation = /(test|tests|smoke|prueba|pruebas|valid|verif|check|comprob)/.test(normalizedGoal);
  const wantsBuild = /(build|bundle|compil|empaquet)/.test(normalizedGoal);
  const wantsLint = /lint/.test(normalizedGoal);
  const wantsGitInstall = /\b(instala|instalar|install|instale|setup)\b/.test(normalizedGoal) && /\bgit\b/.test(normalizedGoal);
  const wantsDirectoryInspect = /\b(revisa|revise|inspecciona|inspeccione|lista|ls|verifica|verifique)\b/.test(normalizedGoal) && /\b(carpeta|directorio|ruta)\b/.test(normalizedGoal);
  const wantsDelete = /\b(borra|borrar|elimina|eliminar|delete|remove|rm)\b/.test(normalizedGoal);
  const wantsProviderCatalogDiagnosis = isProviderCatalogDiagnosticGoal(goal);
  const wantsAgentAutonomyDiagnosis = isAgentAutonomyDiagnosticGoal(goal);

  const requestedDirectory = parseCreateDirectoryIntent(focusedGoal);
  if (requestedDirectory) {
    actions.push({ type: 'mkdir', path: requestedDirectory, allowAbsolute: true });
  }

  const absolutePaths = parseAbsolutePathCandidates(focusedGoal);
  if (wantsDelete) {
    for (const candidate of [...referencedPaths, ...absolutePaths].slice(0, 3)) {
      actions.push({ type: 'delete', path: candidate, allowAbsolute: true, recursive: true });
    }
  }
  if (wantsDirectoryInspect && absolutePaths.length > 0) {
    for (const candidate of absolutePaths.slice(0, 3)) {
      actions.push({ type: 'inspect_path', path: candidate, allowAbsolute: true });
    }
  }

  const explicitExecMatch = focusedGoal.match(/(?:ejecuta|corre|run)\s+(?:el\s+)?(?:comando\s*)?[`"]([^`"\n]+)[`"]/i)
    || focusedGoal.match(/comando:\s*([^\n]+)/i);
  if (explicitExecMatch && explicitExecMatch[1]) {
    actions.push({ type: 'exec', commandLine: String(explicitExecMatch[1]).trim() });
  }

  if (wantsGitInstall) {
    actions.push({ type: 'system_install', package: 'git' });
  }

  if (wantsValidation) {
    if (scripts.includes('test')) {
      addHeuristicVerify(actions, addedCommands, 'npm', ['test']);
    } else if (scripts.includes('smoke')) {
      addHeuristicVerify(actions, addedCommands, 'npm', ['run', 'smoke']);
    }
  }
  if (wantsBuild) {
    if (scripts.includes('build:bundle')) {
      addHeuristicVerify(actions, addedCommands, 'npm', ['run', 'build:bundle']);
    } else if (scripts.includes('build')) {
      addHeuristicVerify(actions, addedCommands, 'npm', ['run', 'build']);
    }
  }
  if (wantsLint && scripts.includes('lint')) {
    addHeuristicVerify(actions, addedCommands, 'npm', ['run', 'lint']);
  }

  if (wantsProviderCatalogDiagnosis) {
    for (const candidate of [
      'package.json',
      'src-js/core/provider-registry.js',
      'src-js/core/control-panel.js',
      'src-js/core/extension.runtime.js',
      'copilot-agent/panel-state.json',
    ]) {
      if (!addedReads.has(candidate) && fileExistsInWorkspace(workspacePath, candidate)) {
        addedReads.add(candidate);
        actions.push({ type: 'read', path: candidate });
      }
    }
  }

  if (wantsAgentAutonomyDiagnosis) {
    for (const candidate of [
      'package.json',
      'src-js/core/extension.runtime.js',
      'src-js/core/freejt7-agent-runtime.js',
      'src-js/core/local-agent-runtime.js',
      'src-js/core/openclaw-agent-runtime.js',
      'src-js/core/control-panel.js',
    ]) {
      if (!addedReads.has(candidate) && fileExistsInWorkspace(workspacePath, candidate)) {
        addedReads.add(candidate);
        actions.push({ type: 'read', path: candidate });
      }
    }
  }

  return actions;
}

function deriveLocalActions(goal, options = {}) {
  const workspacePath = path.resolve(options.workspacePath || process.cwd());
  const packageSummary = readPackageSummary(workspacePath);
  return inferHeuristicActions(workspacePath, goal, packageSummary, {
    ...options,
    actions: [],
    readFiles: [],
    writeFiles: [],
    verificationCommands: [],
  });
}

function summarizeReadResult(read) {
  const firstLine = String(read.content || '').split(/\r?\n/).map((line) => line.trim()).find(Boolean) || 'sin contenido visible';
  return `${read.path}: ${truncate(firstLine, 160)}`;
}

function summarizeVerifyResult(result) {
  const headline = String(result.output || '').split(/\r?\n/).map((line) => line.trim()).find(Boolean) || 'sin salida';
  return `${result.command} (exit=${result.exitCode}): ${truncate(headline, 160)}`;
}

function summarizeSystemAction(result) {
  const headline = String(result.output || '').split(/\r?\n/).map((line) => line.trim()).find(Boolean) || 'sin salida';
  const binaryInfo = result.binaryPath ? ` (${result.binaryPath})` : '';
  return `${result.package}: ${result.status}${binaryInfo}: ${truncate(headline, 160)}`;
}

function summarizeCapabilityDispatch(capabilityPlan = null) {
  if (!capabilityPlan || typeof capabilityPlan !== 'object') {
    return '';
  }
  const dispatch = capabilityPlan.dispatch && typeof capabilityPlan.dispatch === 'object'
    ? capabilityPlan.dispatch
    : null;
  if (!dispatch) {
    return '';
  }
  const parts = [
    `owner=${String(dispatch.owner || 'unknown')}`,
    `target=${String(dispatch.dispatchTarget || 'n/a')}`,
    `skills=${Array.isArray(capabilityPlan.selectedSkills) ? capabilityPlan.selectedSkills.length : 0}`,
    `mcp=${Array.isArray(capabilityPlan.mcpServers) ? capabilityPlan.mcpServers.filter((item) => item && item.enabled !== false).length : 0}`,
    `tools=${Array.isArray(capabilityPlan.plannedActions) ? capabilityPlan.plannedActions.length : 0}`,
  ];
  const trace = Array.isArray(dispatch.trace) ? dispatch.trace.slice(0, 6).join(', ') : '';
  return `${parts.join(' | ')}${trace ? ` | trace=${trace}` : ''}`;
}

function summarizeInspection(result) {
  if (!result.exists) {
    return `${result.path}: missing`;
  }
  if (result.kind === 'dir') {
    return `${result.path}: dir (${result.entries.length} entradas visibles)`;
  }
  return `${result.path}: file`;
}

function summarizeDeleteResult(result) {
  if (result.missing) {
    return `${result.path}: missing`;
  }
  return `${result.path}: removed ${result.kind}`;
}

function summarizeExecResult(result) {
  const headline = String(result.output || '').split(/\r?\n/).map((line) => line.trim()).find(Boolean) || 'sin salida';
  return `${result.command} (exit=${result.exitCode}${result.blocked ? ', blocked' : ''}): ${truncate(headline, 160)}`;
}

function isProviderCatalogDiagnosticGoal(goal) {
  const text = String(extractFocusedText(goal) || '').toLowerCase();
  if (!text) {
    return false;
  }
  return /(?:porque|por que|why).*(?:no aparece|no sale|no se muestra)|(?:no aparece|no sale|no se muestra).*(?:proveedor|provider|modelo|model)|(?:lista|interfaz|panel).*(?:proveedor|provider|modelo|model)|(?:proveedor|provider).*(?:deepseek|ddeksee)|(?:modelo|model).*(?:deepseek|ddeksee)/i.test(text);
}

function isAgentAutonomyDiagnosticGoal(goal) {
  const text = String(extractFocusedText(goal) || '').toLowerCase();
  if (!text) {
    return false;
  }
  return /(?:po?r? ?que|porque|why).*(?:modo agente|agente).*(?:no funciona|no actua|no actúa|no responde|falla)|(?:chat basico|chat básico)|(?:verdadero agente ?autonomo|verdadero agente ?autónomo|agente ?autonomo|agente ?autónomo|agenteautonomo)|(?:protagonista|dueñ[oa] del ide)|(?:po?r? ?que|porque).*(?:no eres|no actuas|no actúas).*(?:agente|autonom)/i.test(text);
}

function analyzeProviderCatalogEvidence(reads = []) {
  const hasPackageEnum = reads.some((item) => item.path === 'package.json' && /"ddeksee"/.test(String(item.content || '')));
  const hasRegistryProvider = reads.some((item) => /provider-registry\.js$/.test(item.path) && /\bid:\s*['"]ddeksee['"]/.test(String(item.content || '')));
  const hasDeepSeekLabel = reads.some((item) => /provider-registry\.js$/.test(item.path) && /\blabel:\s*['"]DeepSeek['"]/.test(String(item.content || '')));
  const hasPanelProvider = reads.some((item) => /control-panel\.js$/.test(item.path) && /ddeksee/.test(String(item.content || '')));
  const hasRuntimeQuickPick = reads.some((item) => /extension\.runtime\.js$/.test(item.path) && /listSelectableApiProviders/.test(String(item.content || '')) && /ddeksee|DeepSeek/.test(String(item.content || '')));
  return {
    hasPackageEnum,
    hasRegistryProvider,
    hasDeepSeekLabel,
    hasPanelProvider,
    hasRuntimeQuickPick,
    registeredInRepo: hasPackageEnum && hasRegistryProvider,
  };
}

function classifyFallbackReason(fallbackReason) {
  const text = String(fallbackReason || '').trim();
  if (!text) {
    return { kind: 'none', detail: '' };
  }
  if (/\b403\b|status code 403|auth|api key|token expired|incorrect/i.test(text)) {
    return {
      kind: 'auth',
      detail: 'El proveedor activo rechazo la ejecucion del motor agente por autenticacion o permisos del modelo.',
    };
  }
  if (/network connection error|econn|enotfound|timeout|socket hang up/i.test(text)) {
    return {
      kind: 'network',
      detail: 'El motor agente no pudo completar la llamada remota por un fallo de red o timeout.',
    };
  }
  if (/loopback|start the gateway|gateway|1006|bind:/i.test(text)) {
    return {
      kind: 'gateway',
      detail: 'El runtime de OpenClaw no quedo operativo a tiempo y la solicitud degrado a herramientas locales.',
    };
  }
  return {
    kind: 'generic',
    detail: 'El motor agente principal no estuvo disponible y la solicitud paso a la ruta local segura.',
  };
}

function summarizeFallbackReasonForUser(fallbackInfo = {}) {
  if (!fallbackInfo || fallbackInfo.kind === 'none') {
    return 'Free JT7 respondio con la ruta local de herramientas.';
  }
  if (fallbackInfo.kind === 'auth') {
    return 'Free JT7 activó su ruta local porque el backend subordinado rechazó autenticación o permisos.';
  }
  if (fallbackInfo.kind === 'network') {
    return 'Free JT7 activó su ruta local porque el backend subordinado no estuvo disponible por red o timeout.';
  }
  if (fallbackInfo.kind === 'gateway') {
    return 'Free JT7 activó su ruta local porque el backend subordinado del harness no quedó operativo a tiempo.';
  }
  return 'Free JT7 activó su ruta local porque el backend subordinado principal no estuvo disponible.';
}

function isSimpleConversationalGoal(goalText) {
  const text = String(goalText || '').trim().toLowerCase();
  if (!text) {
    return false;
  }
  return /^(hola|buenas|buenos dias|buen día|buen dia|buenas tardes|buenas noches|gracias|ok|vale|perfecto|entendido)[!. ]*$/i.test(text);
}

function buildGoalAwareSummary(goal, context = {}) {
  const goalText = extractFocusedGoal(goal);
  const lines = [];
  if (goalText) {
    lines.push(`Objetivo solicitado: ${goalText}`);
  }

  if (/(proveedor|provider|modelo|model|runtime|backend)/i.test(goalText)) {
    lines.push(`Contexto de ejecucion local: proveedor ${context.provider || 'local'}, modelo ${context.model || 'freejt7-local-tools'}, runtime local.`);
  }

  if (Array.isArray(context.heuristicActions) && context.heuristicActions.length > 0) {
    const heuristicLabels = context.heuristicActions.map((action) => {
      if (action.type === 'read') {
        return `leer ${action.path}`;
      }
      if (action.type === 'delete') {
        return `borrar ${action.path}`;
      }
      if (action.type === 'exec') {
        return String(action.commandLine || action.command || 'exec');
      }
      if (action.type === 'verify') {
        return [action.command, ...(action.args || [])].join(' ');
      }
      return action.type;
    });
    lines.push(`Acciones inferidas desde el objetivo: ${heuristicLabels.join(', ')}.`);
  } else if (isIncompleteCreateDirectoryIntent(goalText)) {
    lines.push('La solicitud pide crear una carpeta, pero no incluye una ruta completa o una ruta base con nombre para ejecutarla localmente.');
  }

  if (Array.isArray(context.reads) && context.reads.length > 0) {
    lines.push(`Archivos inspeccionados: ${context.reads.map((item) => summarizeReadResult(item)).join(' | ')}`);
  }

  if (Array.isArray(context.verificationResults) && context.verificationResults.length > 0) {
    lines.push(`Verificaciones ejecutadas: ${context.verificationResults.map((item) => summarizeVerifyResult(item)).join(' | ')}`);
  }

  if ((!context.reads || context.reads.length === 0) && (!context.verificationResults || context.verificationResults.length === 0)) {
    lines.push('No hubo suficientes senales en el objetivo para inferir una accion local mas profunda; se mantuvo una auditoria basica del workspace.');
  }

  return lines;
}

function buildConversationalSummary(goal, context = {}) {
  const goalText = extractFocusedGoal(goal);
  const provider = String(context.provider || 'local').trim() || 'local';
  const model = String(context.model || 'freejt7-local-tools').trim() || 'freejt7-local-tools';
  const fallbackReason = String(context.fallbackReason || '').trim();
  const packageSummary = context.packageSummary || null;
  const workspace = context.workspace || {};
  const reads = Array.isArray(context.reads) ? context.reads : [];
  const writes = Array.isArray(context.writes) ? context.writes : [];
  const dirActions = Array.isArray(context.dirActions) ? context.dirActions : [];
  const deleteActions = Array.isArray(context.deleteActions) ? context.deleteActions : [];
  const inspections = Array.isArray(context.inspections) ? context.inspections : [];
  const failures = Array.isArray(context.failures) ? context.failures : [];
  const verificationResults = Array.isArray(context.verificationResults) ? context.verificationResults : [];
  const execResults = Array.isArray(context.execResults) ? context.execResults : [];
  const systemActions = Array.isArray(context.systemActions) ? context.systemActions : [];
  const heuristicActions = Array.isArray(context.heuristicActions) ? context.heuristicActions : [];
  const paragraphs = [];
  const fallbackInfo = classifyFallbackReason(fallbackReason);
  const providerCatalogDiagnostic = isProviderCatalogDiagnosticGoal(goalText);
  const providerCatalogEvidence = analyzeProviderCatalogEvidence(reads);
  const autonomyDiagnostic = isAgentAutonomyDiagnosticGoal(goalText);

  if (isSimpleConversationalGoal(goalText)) {
    const opening = /^gracias|^ok|^vale|^perfecto|^entendido/i.test(goalText)
      ? 'Entendido.'
      : 'Hola.';
    const shortReply = [opening];
    if (fallbackInfo.kind === 'auth') {
      shortReply.push('El backend principal no estuvo disponible por autenticación o permisos del proveedor activo.');
    } else if (fallbackInfo.kind === 'gateway' || fallbackInfo.kind === 'network') {
      shortReply.push('El backend principal no estuvo disponible en este intento.');
    }
    shortReply.push('Dime la tarea concreta y la ejecuto o la verifico desde el agente.');
    return shortReply.join('\n\n');
  }

  if (!dirActions.length && !inspections.length && !writes.length && !systemActions.length && !failures.length && isIncompleteCreateDirectoryIntent(goalText)) {
    return [
      'Necesito la ruta completa de la carpeta, o una ruta base y el nombre, para poder crearla.',
      'Ejemplo: `crea la carpeta /ruta/proyecto/tmp` o `crea una carpeta en /ruta/proyecto con nombre prueba 3`.',
    ].join('\n\n');
  }

  if (dirActions.length > 0 && failures.length === 0) {
    const created = dirActions[0];
    const actionLine = created.created
      ? `La carpeta \`${created.path}\` fue creada y verificada.`
      : `La carpeta \`${created.path}\` ya existia y verifique que sigue disponible.`;
    const notes = [actionLine];
    if (fallbackReason) {
      notes.push('La ejecucion salio por herramientas locales porque el motor agente no estuvo disponible.');
    }
    return notes.join('\n\n');
  }

  if (inspections.length > 0 && failures.length === 0) {
    const inspection = inspections[0];
    if (!inspection.exists) {
      return `Revise \`${inspection.path}\` y esa ruta no existe en este momento.`;
    }
    if (inspection.kind === 'dir') {
      const entries = inspection.entries.slice(0, 8).join(', ');
      return entries
        ? `Revise \`${inspection.path}\`. Existe y contiene: ${entries}.`
        : `Revise \`${inspection.path}\`. Existe, pero no tiene entradas visibles en el limite inspeccionado.`;
    }
    return `Revise \`${inspection.path}\`. La ruta existe y corresponde a un archivo.`;
  }

  if (deleteActions.length > 0 && failures.length === 0) {
    const removed = deleteActions[0];
    if (removed.missing) {
      return `Revise \`${removed.path}\` para borrarlo, pero esa ruta ya no existe.`;
    }
    return `Elimine \`${removed.path}\` y verifique que ya no permanece en la ruta objetivo.`;
  }

  if (execResults.length > 0 && failures.length === 0) {
    const result = execResults[0];
    if (result.blocked) {
      return `No ejecute \`${result.command}\` porque fue clasificado como comando bloqueado o riesgoso.`;
    }
    return `Ejecute \`${result.command}\` con salida verificada (exit=${result.exitCode}).`;
  }

  if (systemActions.length > 0 && failures.length === 0) {
    const systemAction = systemActions[0];
    if (systemAction.status === 'already_installed') {
      const notes = [`${systemAction.package} ya estaba instalado${systemAction.binaryPath ? ` en \`${systemAction.binaryPath}\`` : ''}. No ejecute una instalacion redundante.`];
      if (fallbackReason) {
        notes.push('La ejecucion salio por herramientas locales porque el motor agente no estuvo disponible.');
      }
      return notes.join('\n\n');
    }
    if (systemAction.status === 'installed') {
      return `Instale ${systemAction.package} y verifique que quedo disponible.`;
    }
    if (systemAction.status === 'blocked' || systemAction.blocked) {
      if (/sudo|contraseñ|contrasena|password/i.test(String(systemAction.output || ''))) {
        return `No pude completar la instalacion de ${systemAction.package} porque el host exigio una contraseña sudo interactiva.`;
      }
      return `No pude completar la instalacion de ${systemAction.package}. El bloqueo vino del host o del gestor de paquetes.`;
    }
  }

  if (providerCatalogDiagnostic && providerCatalogEvidence.registeredInRepo) {
    return [
      'Diagnóstico local: en este repo el provider DeepSeek sí está registrado.',
      providerCatalogEvidence.hasPackageEnum ? 'package.json ya expone `ddeksee` en la configuración del proveedor.' : '',
      providerCatalogEvidence.hasDeepSeekLabel ? 'provider-registry ya publica la etiqueta visible `DeepSeek`.' : '',
      providerCatalogEvidence.hasPanelProvider ? 'control-panel ya incluye `ddeksee` en el catálogo del panel.' : '',
      providerCatalogEvidence.hasRuntimeQuickPick ? 'extension.runtime ya lo expone en los selectores del IDE.' : '',
      'Si no aparece en la IDE, la causa probable ya no es el código fuente del repo sino la extensión instalada o el estado persistido del perfil.',
    ].filter(Boolean).join('\n\n');
  }

  if (autonomyDiagnostic) {
    return [
      'Diagnóstico local: Free JT7 todavía cayó a ruta local porque el motor agente principal no estuvo disponible en este intento.',
      fallbackInfo.detail ? `Causa operativa inmediata: ${fallbackInfo.detail}` : '',
      'Causa estructural visible: el runtime propio ya es el control-plane, pero cuando OpenClaw o el backend remoto fallan el flujo sigue degradando a fallback local para no mentir sobre ejecución.',
      reads.some((item) => /freejt7-agent-runtime\.js$/.test(item.path)) ? 'Evidencia de diseño: `freejt7-agent-runtime` ya decide la ruta principal y los fallbacks.' : '',
      reads.some((item) => /control-panel\.js$/.test(item.path)) ? 'Evidencia de superficie: el panel propio ya actúa como interfaz principal del agente y no depende del chat host para operar.' : '',
      'Lo que falta para sentirse como agente autónomo completo no es "más chat", sino que el backend principal falle menos y que la degradación local sea aún más ejecutora y menos explicativa.',
    ].filter(Boolean).join('\n\n');
  }

  const intro = summarizeFallbackReasonForUser(fallbackInfo);
  paragraphs.push(intro);

  if (goalText) {
    paragraphs.push(`Solicitud atendida: ${goalText}`);
  }

  if (fallbackInfo.detail && /(por que|porque).*\bagente\b|\bno estas usando el agente\b/i.test(goalText)) {
    paragraphs.push(`Motivo operativo: ${fallbackInfo.detail}`);
  }

  if (/(proveedor|provider|modelo|model|runtime|backend)/i.test(goalText)) {
    paragraphs.push(`Ruta activa visible: proveedor ${provider}, modelo ${model}, backend local.`);
  }

  const evidence = [];
  if (packageSummary && !packageSummary.error) {
    const scriptCount = Array.isArray(packageSummary.scripts) ? packageSummary.scripts.length : 0;
    evidence.push(`proyecto npm ${packageSummary.name || 'sin nombre'} ${packageSummary.version || ''}`.trim());
    if (scriptCount) {
      evidence.push(`${scriptCount} scripts disponibles`);
    }
  }
  if (workspace.root) {
    evidence.push(`${Number(workspace.dirs || 0)} directorios y ${Number(workspace.files || 0)} archivos directos visibles`);
  }
  if (reads.length) {
    evidence.push(`lecturas: ${reads.map((item) => item.path).slice(0, 4).join(', ')}`);
  }
  if (writes.length) {
    evidence.push(`escrituras verificadas: ${writes.map((item) => item.path).slice(0, 4).join(', ')}`);
  }
  if (dirActions.length) {
    evidence.push(`directorios: ${dirActions.map((item) => item.path).slice(0, 4).join(', ')}`);
  }
  if (deleteActions.length) {
    evidence.push(`borrados: ${deleteActions.map((item) => summarizeDeleteResult(item)).slice(0, 4).join('; ')}`);
  }
  if (inspections.length) {
    evidence.push(`rutas inspeccionadas: ${inspections.map((item) => summarizeInspection(item)).slice(0, 3).join('; ')}`);
  }
  if (verificationResults.length) {
    const okCount = verificationResults.filter((item) => Number(item.exitCode) === 0).length;
    evidence.push(`verificaciones: ${okCount}/${verificationResults.length} OK`);
  }
  if (systemActions.length) {
    evidence.push(`sistema: ${systemActions.map((item) => summarizeSystemAction(item)).join('; ')}`);
  }
  if (execResults.length) {
    evidence.push(`exec: ${execResults.map((item) => summarizeExecResult(item)).join('; ')}`);
  }
  if (evidence.length) {
    paragraphs.push(`Evidencia breve: ${evidence.join('; ')}.`);
  }

  if (failures.length) {
    paragraphs.push(`Atencion: ${failures.length} accion local fue bloqueada o fallo. Revisa el inspector de tareas para el detalle tecnico.`);
  }

  const hasResolvedSystemAction = systemActions.some((item) => item.status === 'already_installed' || item.status === 'installed');

  if (systemActions.some((item) => item.status === 'already_installed')) {
    const packages = systemActions
      .filter((item) => item.status === 'already_installed')
      .map((item) => item.package)
      .join(', ');
    paragraphs.push(`Resultado: ${packages} ya estaba instalado. No ejecute una instalacion redundante.`);
  } else if (systemActions.some((item) => item.status === 'installed')) {
    const packages = systemActions
      .filter((item) => item.status === 'installed')
      .map((item) => item.package)
      .join(', ');
    paragraphs.push(`Resultado: instalacion completada para ${packages}.`);
  } else if (systemActions.some((item) => item.status === 'blocked' || item.blocked)) {
    const sudoBlocked = systemActions.some((item) => /sudo|contraseñ|contrasena|password/i.test(String(item.output || '')));
    if (sudoBlocked) {
      paragraphs.push('Resultado: no pude completar la instalacion de sistema porque el host exigio una contraseña sudo interactiva.');
    } else {
      paragraphs.push('Resultado: la instalacion de sistema fue bloqueada por privilegios o gestor no disponible. El inspector contiene el motivo exacto.');
    }
  }

  if (hasResolvedSystemAction && /\bgit\b/i.test(goalText)) {
    paragraphs.push('Siguiente paso ejecutable: ya puedes usar `git --version` o continuar con la operacion Git que necesitabas.');
  } else if (systemActions.some((item) => item.status === 'blocked' || item.blocked) && /\bgit\b/i.test(goalText)) {
    paragraphs.push('Siguiente paso ejecutable: abre una terminal del sistema con privilegios y ejecuta la instalacion, o corrige el PATH del host si Git ya existe fuera del entorno de la extension.');
  } else if (heuristicActions.length) {
    const labels = heuristicActions.map((action) => {
      if (action.type === 'read') return `leer ${action.path}`;
      if (action.type === 'verify') return [action.command, ...(action.args || [])].join(' ');
      return String(action.type || 'accion');
    });
    paragraphs.push(`Siguiente paso ejecutable inferido: ${labels.slice(0, 4).join(', ')}.`);
  } else if (/(proveedor|provider|modelo|model|runtime|backend)/i.test(goalText)) {
    paragraphs.push('Siguiente paso ejecutable: cambia proveedor/modelo desde el inspector lateral o ejecuta una prueba de proveedor para confirmar disponibilidad real.');
  } else if (!reads.length && !writes.length && verificationResults.length <= SAFE_COMMANDS.length) {
    paragraphs.push('Siguiente paso ejecutable: concreta el archivo, prueba o cambio esperado para que el agente pueda pasar de auditoria basica a accion verificable.');
  }

  return paragraphs.filter(Boolean).join('\n\n');
}

async function runLocalAgentTask(goal, options = {}) {
  const workspacePath = path.resolve(options.workspacePath || process.cwd());
  const provider = String(options.provider || 'local').trim() || 'local';
  const model = String(options.model || 'freejt7-local-tools').trim() || 'freejt7-local-tools';
  const technicalSummaryLines = [];
  const verification = [];
  const toolResults = [];
  const workspace = listWorkspace(workspacePath);
  const packageSummary = readPackageSummary(workspacePath);
  const heuristicActions = inferHeuristicActions(workspacePath, goal, packageSummary, options);
  const actionResults = executeLocalActions(workspacePath, {
    ...options,
    actions: [...getActionList(options), ...heuristicActions],
  });
  for (const spec of SAFE_COMMANDS) {
    toolResults.push(runSafeCommand(spec, workspacePath));
  }

  technicalSummaryLines.push('Free JT7 ejecuto una ruta local de agente con herramientas basicas, sin depender de Copilot ni OpenClaw.');
  if (options.fallbackReason) {
    technicalSummaryLines.push(`Motivo del fallback local: ${String(options.fallbackReason).trim()}`);
  }
  const capabilityDispatchSummary = summarizeCapabilityDispatch(options.capabilityPlan || null);
  if (capabilityDispatchSummary) {
    technicalSummaryLines.push(`Dispatch nativo del runtime: ${capabilityDispatchSummary}`);
  }
  technicalSummaryLines.push(`Workspace: ${workspace.root}`);
  technicalSummaryLines.push(`Contenido directo visible: ${workspace.dirs} directorios y ${workspace.files} archivos.`);
  if (packageSummary && !packageSummary.error) {
    technicalSummaryLines.push(`Proyecto npm: ${packageSummary.name || 'sin nombre'} ${packageSummary.version || ''}`.trim());
    if (packageSummary.scripts.length) {
      technicalSummaryLines.push(`Scripts detectados: ${packageSummary.scripts.slice(0, 12).join(', ')}`);
    }
  }
  if (actionResults.reads.length) {
    technicalSummaryLines.push(`Lecturas workspace-safe: ${actionResults.reads.map((item) => item.path).join(', ')}.`);
  }
  if (actionResults.writes.length) {
    technicalSummaryLines.push(`Escrituras workspace-safe verificadas: ${actionResults.writes.map((item) => item.path).join(', ')}.`);
  }
  if (actionResults.dirActions.length) {
    technicalSummaryLines.push(`Directorios verificados: ${actionResults.dirActions.map((item) => item.path).join(', ')}.`);
  }
  if (actionResults.deleteActions.length) {
    technicalSummaryLines.push(`Borrados verificados: ${actionResults.deleteActions.map((item) => summarizeDeleteResult(item)).join(' | ')}.`);
  }
  if (actionResults.inspections.length) {
    technicalSummaryLines.push(`Rutas inspeccionadas: ${actionResults.inspections.map((item) => summarizeInspection(item)).join(' | ')}.`);
  }
  if (actionResults.execResults.length) {
    technicalSummaryLines.push(`Comandos ejecutados: ${actionResults.execResults.map((item) => summarizeExecResult(item)).join(' | ')}`);
  }
  if (actionResults.systemActions.length) {
    technicalSummaryLines.push(`Acciones de sistema: ${actionResults.systemActions.map((item) => summarizeSystemAction(item)).join(' | ')}`);
  }
  if (actionResults.failures.length) {
    technicalSummaryLines.push(`Acciones locales bloqueadas/fallidas: ${actionResults.failures.length}.`);
  }
  technicalSummaryLines.push(...buildGoalAwareSummary(goal, {
    provider,
    model,
    heuristicActions,
    reads: actionResults.reads,
    deleteActions: actionResults.deleteActions,
    verificationResults: [...toolResults, ...actionResults.verificationResults],
    execResults: actionResults.execResults,
    systemActions: actionResults.systemActions,
  }));
  const visibleSummary = buildConversationalSummary(goal, {
    provider,
    model,
    fallbackReason: options.fallbackReason,
    workspace,
    packageSummary,
    heuristicActions,
    reads: actionResults.reads,
    dirActions: actionResults.dirActions,
    deleteActions: actionResults.deleteActions,
    inspections: actionResults.inspections,
    writes: actionResults.writes,
    failures: actionResults.failures,
    verificationResults: [...toolResults, ...actionResults.verificationResults],
    execResults: actionResults.execResults,
    systemActions: actionResults.systemActions,
  });
  const technicalSummary = technicalSummaryLines.join('\n');

  verification.push('LocalAgent: listado de workspace ejecutado.');
  if (capabilityDispatchSummary) {
    verification.push(`LocalAgent: runtime dispatch ${capabilityDispatchSummary}.`);
  }
  for (const read of actionResults.reads) {
    verification.push(`LocalAgent: lectura workspace-safe ${read.path}${read.truncated ? ' (truncada)' : ''}.`);
  }
  for (const write of actionResults.writes) {
    verification.push(`LocalAgent: escritura verificada por readback ${write.path}.`);
  }
  for (const dirAction of actionResults.dirActions) {
    verification.push(`LocalAgent: directorio ${dirAction.path} ${dirAction.created ? 'creado' : 'ya existente'} y verificado.`);
  }
  for (const deleteAction of actionResults.deleteActions) {
    verification.push(`LocalAgent: borrado ${deleteAction.path} removed=${deleteAction.removed} missing=${deleteAction.missing}.`);
  }
  for (const inspection of actionResults.inspections) {
    verification.push(`LocalAgent: inspeccion ${inspection.path} exists=${inspection.exists} kind=${inspection.kind}.`);
  }
  for (const result of toolResults) {
    verification.push(`LocalAgent: ${result.command} exit=${result.exitCode}.`);
  }
  for (const result of actionResults.verificationResults) {
    verification.push(`LocalAgent: verificacion ${result.command} exit=${result.exitCode}${result.blocked ? ' blocked' : ''}.`);
  }
  for (const result of actionResults.execResults) {
    verification.push(`LocalAgent: exec ${result.command} exit=${result.exitCode}${result.blocked ? ' blocked' : ''}.`);
  }
  for (const result of actionResults.systemActions) {
    verification.push(`LocalAgent: system_install ${result.package} status=${result.status}${result.exitCode !== undefined ? ` exit=${result.exitCode}` : ''}.`);
  }
  for (const failure of actionResults.failures) {
    verification.push(`LocalAgent: accion ${failure.type} fallida/bloqueada ${failure.path || ''}: ${failure.error}`.trim());
  }

  return {
    provider,
    model,
    executionMode: 'agent',
    executionRoute: 'local-agent-tools',
    local: {
      goal: String(goal || ''),
      workspace,
      packageSummary,
      toolResults,
      heuristicActions,
      actions: actionResults,
      technicalSummary,
    },
    run: {
      status: 'completed',
      summary: visibleSummary,
      provider,
      model,
    },
    final: {
      status: 'completed',
      summary: visibleSummary,
      changedFiles: [
        ...actionResults.writes.map((item) => item.path),
        ...actionResults.dirActions.map((item) => item.path),
        ...actionResults.deleteActions.map((item) => item.path),
      ],
      verification,
      residualRisks: [
        'La ruta local ejecuta herramientas deterministas basicas; para edicion compleja sigue siendo necesario un motor agente completo o una fase de implementacion especifica.',
      ],
    },
  };
}

